insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('side-grechka', 'Гречка', 'Рассыпчатая гречка со сливочным маслом — к мясу, рыбе и котлетам', 'side', array['lunch','dinner']::text[], 5, 25, 4, 3, 'none', array['быстро','будни','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Подходит. Солить умеренно.', array['Гречку перебрать и промыть.','Залить 500 мл кипятка, посолить и довести до кипения.','Варить под крышкой на слабом огне 15–20 минут, пока вода не впитается.','Добавить масло, перемешать и дать постоять 5 минут.']::text[], 'https://1000.menu/cooking/17422-rassypchataya-grechka-na-garnir', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
