insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('side-pyure', 'Картофельное пюре', 'Нежное пюре на молоке со сливочным маслом', 'side', array['lunch','dinner']::text[], 15, 35, 4, 2, 'none', array['будни','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Подходит. Его порцию отложить до досаливания.', array['Картошку почистить, нарезать крупно, залить водой и посолить.','Варить 20 минут после закипания, пока не станет мягкой.','Слить воду, добавить масло и горячее молоко.','Растолочь толкушкой до однородности.']::text[], 'https://www.iamcook.ru/showrecipe/573', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
