insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('side-kartofel-zapechenny', 'Картофель, запечённый дольками', 'Картошка дольками с румяной корочкой, почти без участия повара', 'side', array['lunch','dinner']::text[], 10, 45, 4, 2, 'none', array['будни','духовка','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его дольки очистить от кожуры и перемешать с маслом и солью отдельно, без чеснока.', array['Включить духовку на 200 °C.','Картошку хорошо вымыть и нарезать дольками, кожуру можно оставить.','Перемешать с маслом, паприкой, солью и рубленым чесноком.','Выложить в один слой на противень с пергаментом и запекать 35 минут, один раз перевернув.']::text[], 'https://1000.menu/cooking/24356-kartofelnye-dolki-zapechennye-v-duxovke', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
