insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('side-perlovka', 'Перловка', 'Дешёвая и сытная крупа; варится долго, зато хранится три дня', 'side', array['lunch','dinner']::text[], 10, 70, 4, 3, 'none', array['бюджетное','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'ok', 'Подходит, если хорошо разварить.', array['Перловку промыть. Если есть время, замочить в холодной воде на ночь — сварится быстрее.','Залить 750 мл воды, довести до кипения и посолить.','Варить под крышкой на слабом огне 50–60 минут без замачивания или 30–40 после него.','Добавить масло и дать постоять 10 минут.']::text[], 'https://1000.menu/cooking/24255-perlovaya-kasha-na-vode', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
