insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('side-kapusta-tushenaya', 'Тушёная капуста', 'Капуста, тушённая с морковью и томатом, — к котлетам и рыбе', 'side', array['lunch','dinner']::text[], 15, 50, 4, 3, 'none', array['бюджетное','постное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Подходит, если капуста мягкая. Лавровый лист вынуть.', array['Капусту нашинковать, морковь натереть, лук мелко нарезать.','Обжарить лук и морковь на масле в глубокой сковороде 5 минут.','Добавить капусту, посолить, влить 100 мл воды и тушить под крышкой 25 минут, иногда помешивая.','Добавить томатную пасту и лавровый лист и тушить ещё 10 минут, пока капуста не станет мягкой.']::text[], 'https://menunedeli.ru/recipe/tushenaya-kapusta-s-tomatnoj-pastoj/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
