insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('side-ovoshchi-zapechenye', 'Запечённые овощи', 'Овощи крупными кусками из духовки — без хлопот у плиты', 'side', array['lunch','dinner']::text[], 10, 40, 4, 2, 'none', array['будни','духовка','постное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Запечённые овощи подходят. Нарезать мелко или размять.', array['Включить духовку на 200 °C.','Кабачок и перец нарезать крупно, морковь — брусочками, лук — дольками.','Перемешать овощи с маслом, солью и орегано.','Выложить в один слой на противень и запекать 30 минут до мягкости и румяных краёв.']::text[], 'https://www.edimdoma.ru/retsepty/112801-ovoschi-prosto-ovoschi', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
