insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-lenivaya-ovsyanka', 'Ленивая овсянка в банке', 'Собираем с вечера за 10 минут, утром завтрак ждёт в холодильнике', 'breakfast', array['breakfast','snack']::text[], 10, 10, 4, 2, 'dairy', array['без плиты','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Банан Диме нарезать помельче', array['Вечером взять 4 банки или стакана по 400 мл и насыпать в каждую по 50 г хлопьев.','Банан нарезать кружками и разложить сверху вместе с ягодами, добавить мёд.','Залить каждую порцию йогуртом, закрыть крышкой и хорошо встряхнуть.','Убрать в холодильник на ночь, минимум на 6 часов.','Утром есть холодной или погреть 1–2 минуты в микроволновке.']::text[], 'https://www.gastronom.ru/recipe/37700/lenivaya-ovsyanka-v-banke', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
