insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-ovsyanka-zapechennaya', 'Запечённая овсянка с бананом', 'Каша, которая печётся сама: смешал, поставил в духовку и собираешься', 'breakfast', array['breakfast']::text[], 10, 60, 4, 2, 'egg', array['выходные','духовка','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Чернослив в его кусок порезать совсем мелко', array['Духовку разогреть до 180°. Бананы размять вилкой в пюре.','Добавить яйца, молоко и масло и перемешать венчиком до однородности.','Чернослив промыть и мелко нарезать, всыпать в миску вместе с хлопьями и перемешать.','Выложить массу в форму, застеленную бумагой, и разровнять.','Запекать около 50 минут, пока середина не станет плотной, а верх румяным.','Дать постоять 5 минут, нарезать и подавать тёплой с молоком или йогуртом.']::text[], 'https://www.iamcook.ru/showrecipe/21837', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
