insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-ovsyanka-shokoladnaya', 'Шоколадная овсянка с бананом', 'Какао и банан вместо сахара: эту кашу дети доедают сами', 'breakfast', array['breakfast']::text[], 10, 20, 4, 1, 'dairy', array['быстро','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Какао близко к шоколаду: Диме такую кашу раз-два в неделю, в остальные дни варить ему без какао', array['Хлопья залить молоком с водой и оставить на 10 минут.','Бананы размять вилкой в пюре.','Добавить к хлопьям банан, какао и щепотку соли и перемешать.','Варить на среднем огне 6–7 минут, помешивая, пока каша не загустеет.','Разложить по тарелкам: сахар не нужен, сладость даёт банан.']::text[], 'https://www.iamcook.ru/showrecipe/10041', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
