insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-yachnevaya', 'Ячневая каша на молоке', 'Ячневая крупа — дешёвая и сытная, а на молоке её едят и дети', 'breakfast', array['breakfast']::text[], 10, 40, 4, 1, 'dairy', array['будни','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Мягкая молочная каша — Диме как есть, соли и сахара по минимуму', array['Крупу промыть в нескольких водах, пока вода не станет почти прозрачной.','В кастрюле с толстым дном вскипятить молоко с водой, всыпать крупу и снова довести до кипения.','Убавить огонь до самого слабого и варить 20–25 минут, часто помешивая, чтобы каша не пристала.','По желанию добавить ягоды и проварить ещё 2 минуты.','Посолить, подсластить, накрыть крышкой и дать постоять 10 минут.','Разложить по тарелкам и положить в каждую кусочек масла.']::text[], 'https://www.gastronom.ru/recipe/54828/jachnevaja-kasha-na-moloke', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
