insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-bulgur-molochny', 'Каша из булгура на молоке', 'Булгур на молоке за 25 минут: с ореховым вкусом и изюмом', 'breakfast', array['breakfast']::text[], 10, 25, 4, 1, 'dairy', array['быстро','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Изюм в его порции порезать или вынуть', array['В кастрюле растопить масло, всыпать булгур и обжаривать 2–3 минуты, помешивая, до орехового запаха.','Влить горячее молоко и довести до кипения.','Убавить огонь, добавить сахар и щепотку соли и варить 12 минут, помешивая.','Изюм промыть и положить в кашу на пятой минуте варки.','Выключить огонь, накрыть крышкой и дать постоять 7 минут, чтобы каша загустела.']::text[], 'https://www.gastronom.ru/recipe/63917/kasha-iz-bulgura-na-moloke', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
