insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-pshennaya-yabloki', 'Пшённая каша с яблоками', 'Пшено с яблоком, корицей и ложкой мёда — сладко почти без сахара', 'breakfast', array['breakfast']::text[], 10, 40, 4, 1, 'dairy', array['будни','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Яблоко резать мелко, корицы — щепотку', array['Пшено промыть в нескольких водах, последний раз горячей, чтобы ушла горечь.','Залить водой, слегка посолить и варить на среднем огне, пока вода не впитается.','Яблоки очистить от кожуры и сердцевины и нарезать мелкими кубиками.','Влить тёплое молоко, добавить яблоки и корицу и варить на слабом огне до густоты, помешивая.','Положить мёд и масло, перемешать, накрыть крышкой и оставить на 10 минут.']::text[], 'https://www.iamcook.ru/showrecipe/16517', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
