insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-drachena', 'Драчёна', 'Пышная драчёна из духовки: нежнее омлета, почти суфле', 'breakfast', array['breakfast']::text[], 15, 50, 4, 1, 'egg', array['выходные','духовка','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Запечённое яйцо — Диме как есть, маслом полить совсем немного', array['Духовку разогреть до 170°. Яйца разделить на желтки и белки.','Желтки смешать с молоком, сметаной, солью и мукой до гладкости, без комочков.','Белки взбить до мягких пиков и осторожно вмешать в желтковую массу лопаткой.','Форму щедро смазать маслом, вылить массу и разровнять.','Запекать 30–35 минут, пока драчёна не поднимется, не зарумянится и не пойдёт трещинками.','Полить растопленным маслом и сразу подавать: она быстро оседает.']::text[], 'https://www.iamcook.ru/showrecipe/33590', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
