insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-omlet-kabachok-goroshek', 'Омлет с кабачком и горошком в формочках', 'Омлет с овощами в порционных формочках, собрать можно с вечера', 'breakfast', array['breakfast']::text[], 15, 40, 4, 1, 'egg', array['будни','духовка','детское']::text[], array['summer','autumn']::text[], '{}'::text[], 'ok', 'Запечённый омлет с мягкими овощами — Диме как есть', array['Духовку разогреть до 170°. Кабачок нарезать мелкими кубиками, горошек обдать кипятком в дуршлаге.','Формочки смазать маслом, на дно положить горошек, сверху кабачок.','Яйца взболтать вилкой с молоком, солью и базиликом.','Залить овощи яичной смесью, не доливая до края 1 см: омлет сильно поднимается.','Посыпать тёртым сыром и запекать 25 минут до румяной корочки.','Формочки можно собрать с вечера и убрать в холодильник, утром только запечь.']::text[], 'https://menunedeli.ru/recipe/omlet-s-kabachkom-i-zelenym-goroshkom-zapechennyj-v-duxovke/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
