insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-yaichnica-v-hlebe', 'Яичница в хлебе', 'Глазунья в окошке из хлеба — дети разбирают первыми', 'breakfast', array['breakfast']::text[], 15, 15, 4, 0, 'egg', array['быстро','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его яйцо держать под крышкой до твёрдого желтка, без перца', array['В каждом ломтике хлеба вырезать серединку формочкой или ножом, оставив рамку около 1 см.','Разогреть сковороду с небольшим количеством масла и подрумянить рамки и вырезанные кружки с одной стороны.','Перевернуть и аккуратно вбить в каждое окошко по яйцу, слегка посолить.','Убавить огонь до минимума, накрыть крышкой и держать, пока белок не схватится.','Взрослым поперчить в тарелке, а кружками хлеба удобно макать в желток.']::text[], 'https://www.iamcook.ru/showrecipe/13387', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
