insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-omlet-rulet', 'Омлетный рулет с сыром', 'Тонкие слои омлета с сыром и укропом, свёрнутые рулетом', 'breakfast', array['breakfast']::text[], 20, 20, 4, 1, 'egg', array['быстро','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Тонкий омлет прожаривается целиком, перец — только взрослым в тарелку', array['Яйца перемешать вилкой с молоком и солью. Укроп и болгарский перец мелко нарезать и добавить к яйцам.','Сыр натереть на мелкой тёрке.','Сковороду смазать кисточкой с маслом, разогреть на среднем огне, налить тонкий слой смеси и посыпать сыром.','Когда низ схватится, свернуть омлет рулетом, оставив свободный край, и сдвинуть к бортику.','Налить новую порцию так, чтобы она подтекла под край рулета, посыпать сыром и свернуть дальше. Повторять, пока смесь не кончится.','Дать рулету немного остыть на тарелке и только тогда резать, иначе раскрошится.']::text[], 'https://www.gastronom.ru/recipe/58129/omlet-ruletom-s-syrom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
