insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-frittata-ovoshchi', 'Фриттата с брокколи и стручковой фасолью', 'Овощи и яйца на одной сковороде: начинаем на плите, доводим в духовке', 'breakfast', array['breakfast']::text[], 20, 30, 4, 1, 'egg', array['быстро','духовка','выходные']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме кусочек из середины, овощи в нём порезать мельче; перец — только взрослым', array['Духовку разогреть до 180°. Брокколи разобрать на соцветия, перец нарезать тонкой соломкой, лук — полукольцами.','Чеснок мелко порубить и смешать с соком лимона и оливковым маслом.','На сковороде, которую можно ставить в духовку, растопить сливочное масло и обжарить лук до мягкости.','Добавить брокколи и жарить минуту, затем перец и стручковую фасоль ещё минуту. Влить чесночную заправку и перемешать.','Яйца взболтать с солью и залить овощи. Когда края начнут схватываться, переставить сковороду в духовку на 7–10 минут.','Посыпать зеленью и нарезать, взрослым поперчить в тарелке.']::text[], 'https://eda.rambler.ru/recepty/zavtraki/frittata-s-ovoschami-80164', 'eda.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
