insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-yaichnica-v-lavashe', 'Яичница в лаваше с сыром', 'Яйца, сыр и зелень между двумя кругами лаваша — горячий пирог за 20 минут', 'breakfast', array['breakfast','snack']::text[], 20, 20, 2, 0, 'egg', array['быстро','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Желтки проколоть, чтобы пропеклись полностью; в его кусок без перца', array['Сыр натереть на крупной тёрке, зелень мелко порубить.','Из лаваша вырезать два круга: один по дну сковороды, второй чуть больше.','Сковороду смазать маслом и уложить больший круг так, чтобы получились бортики.','Разбить на лаваш яйца, посолить и посыпать большей частью сыра и зелени.','Накрыть вторым кругом, прижать края и готовить под крышкой на среднем огне около 5 минут.','Перевернуть, посыпать остатком сыра, накрыть и оставить на выключенной плите на 5 минут. Нарезать и подавать.']::text[], 'https://1000.menu/cooking/35069-yaichnica-v-lavashe-na-skovorode-s-syrom', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
