insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-sendvich-omlet', 'Сэндвич с омлетом', 'Омлет с сыром, помидор и салат между двумя тостами', 'breakfast', array['breakfast','snack']::text[], 15, 15, 4, 0, 'egg', array['быстро','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его омлет подержать под крышкой ещё минуту, чтобы схватился полностью; салат порвать мелко', array['На каждый сэндвич взболтать вилкой одно яйцо с 40 мл молока и щепоткой соли.','Растопить на сковороде кусочек масла, вылить смесь и жарить омлет на слабом огне 2 минуты.','Посыпать тёртым сыром и сложить конвертом, чтобы сыр оказался внутри.','На ломтик хлеба положить лист салата, сверху омлет и пару кружков помидора, взрослым поперчить.','Накрыть вторым ломтиком и разрезать по диагонали. Так же собрать остальные.']::text[], 'https://www.iamcook.ru/showrecipe/26024', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
