insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-sloyki-vetchina-syr', 'Слойки с ветчиной и сыром', 'Слойки из готового теста за 40 минут — тёплый завтрак на выходные', 'breakfast', array['breakfast','snack']::text[], 15, 40, 3, 1, 'dairy', array['выходные','духовка','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме 1–2 слойки с сыром и помидором: начинку ему смешать отдельно, без ветчины и лука', array['Духовку разогреть до 180°. Помидор разрезать и слегка отжать сок, затем нарезать мелким кубиком вместе с луком и ветчиной.','Сыр натереть и смешать с остальной начинкой.','Тесто раскатать на подпылённом мукой столе примерно вдвое тоньше и нарезать квадратами 10–12 см.','На середину каждого квадрата положить ложку начинки и соединить уголки в центре.','Выложить на противень с бумагой и смазать взболтанным яйцом.','Выпекать около 20 минут до золотистого цвета.']::text[], 'https://menunedeli.ru/recipe/bystrye-slojki-s-vetchinoj-i-syrom/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
