insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-syrniki-morkov', 'Сырники с морковью', 'Сырники с тушёной морковью: ярче, сочнее и с овощем внутри', 'breakfast', array['breakfast','snack']::text[], 30, 50, 4, 2, 'cottage', array['выходные','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме 2–3 сырника не жарить, а запечь на бумаге в духовке: 180°, 20 минут', array['Морковь натереть на мелкой тёрке и тушить под крышкой со сливочным маслом и водой около 15 минут до мягкости. Остудить.','Творог перемешать с яйцами, сахаром и ванильным сахаром.','Добавить морковь, перемешать и всыпать манку: масса должна держать форму, но не быть крутой.','Сформовать сырники и обвалять в оставшейся манке.','Жарить на растительном масле на среднем огне по 4–5 минут с каждой стороны.','Выложить на салфетку и подавать со сметаной.']::text[], 'https://1000.menu/cooking/24352-syrniki-s-morkovu-i-tvorogom', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
