insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-zapekanka-tykva', 'Творожная запеканка с тыквой', 'Творог и тыква на пару: яркая запеканка, сладкая почти без сахара', 'breakfast', array['breakfast','snack']::text[], 15, 45, 4, 3, 'cottage', array['будни','духовка','детское','на 2–3 дня']::text[], array['autumn','winter']::text[], '{}'::text[], 'ok', 'Диме как есть, сахара по минимуму', array['Тыкву очистить, нарезать кусками и приготовить на пару до мягкости, 15–20 минут.','Тем временем смешать творог, яйца и манку и разогреть духовку до 200°.','Тыкву пробить блендером в пюре и горячей вмешать в творожную массу. Если тыква несладкая, добавить сахар или мёд.','Выложить в смазанную маслом форму и запекать 20 минут до золотистой корочки.','Дать немного остыть и нарезать.']::text[], 'https://www.gastronom.ru/recipe/31242/tvorozhnaya-zapekanka-s-tykvoj', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
