insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-oladi-tvorozhnye', 'Творожные оладьи на кефире', 'Творог в тесте: оладьи пышные под крышкой и не приторные', 'breakfast', array['breakfast','snack']::text[], 25, 30, 4, 1, 'cottage', array['быстро','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме испечь оладьи в духовке на бумаге: 200°, 12–15 минут, перевернуть на середине', array['Творог, кефир и яйцо достать заранее, чтобы согрелись. Рассыпчатый творог протереть через сито.','Цедру лимона натереть и перемешать с сахаром.','Кефир смешать с яйцом, добавить творог, сахар с цедрой и щепотку соли.','Просеять муку с разрыхлителем, перемешать и влить ложку масла: тесто должно быть густым.','Выкладывать ложкой на смазанную маслом сковороду и жарить на умеренном огне 2–3 минуты.','Перевернуть, накрыть крышкой и печь ещё 3 минуты на тихом огне.']::text[], 'https://www.gastronom.ru/recipe/60313/pyshnye-tvorozhnye-oladi-na-kefire', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
