insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-lapshevnik', 'Лапшевник с творогом', 'Сладкая запеканка из лапши и творога, как в детском саду', 'breakfast', array['breakfast','snack']::text[], 20, 55, 6, 2, 'cottage', array['выходные','духовка','детское','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'ok', 'Диме как есть; сахара можно класть вдвое меньше', array['Лапшу отварить в подсоленной воде по времени на пачке, откинуть и немного остудить.','Два яйца взбить венчиком с сахаром и щепоткой соли.','Добавить творог, крупитчатый — протереть или пробить блендером, перемешать и вмешать лапшу.','Духовку разогреть до 180°. Форму смазать маслом и выложить массу.','Оставшиеся яйца смешать со сметаной и залить лапшевник сверху.','Печь 30–40 минут до румяного верха. Подавать со сметаной или вареньем.']::text[], 'https://1000.menu/cooking/40684-lapshevnik-s-tvorogom-v-duxovke', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
