insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-zapekanka-morkovnaya', 'Морковная запеканка', 'Морковь с манкой из духовки, как в садике: сладкая и мягкая', 'breakfast', array['breakfast','snack']::text[], 30, 60, 4, 2, 'egg', array['выходные','духовка','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Мягкая запеканка — Диме как есть', array['Морковь очистить и натереть на тёрке или нарезать тонкой соломкой.','В сковороде растопить масло, выложить морковь, влить молоко и тушить на малом огне до мягкости.','Всыпать манку, сразу перемешать и держать на огне ещё около 10 минут, затем добавить сахар.','Переложить в миску, дать немного остыть и вмешать яйца. Духовку разогреть до 180°.','Форму смазать маслом и присыпать сухарями, выложить массу, разровнять и смазать сметаной.','Печь 20–25 минут, пока верх не зарумянится. Подавать, полив растопленным маслом.']::text[], 'https://www.iamcook.ru/showrecipe/15798', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
