insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-oladi-yabloki', 'Яблочные оладьи на кефире', 'Яблока больше, чем теста: воздушные оладьи на взбитом белке', 'breakfast', array['breakfast','snack']::text[], 25, 40, 4, 1, 'dairy', array['будни','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме испечь оладьи в духовке на бумаге: 200°, 12–15 минут, перевернуть на середине', array['Яйцо разделить на белок и желток. Желток слегка взбить венчиком с кефиром комнатной температуры.','Добавить соль, муку и разрыхлитель и перемешать до гладкости.','Белок взбить с сахаром до крепких пиков и осторожно вмешать в тесто.','Яблоки очистить, натереть на крупной тёрке, сразу сбрызнуть лимонным соком и добавить в тесто.','Накрыть миску полотенцем и оставить на 15 минут.','Жарить ложкой на разогретом масле до золотистого цвета с двух сторон. Подавать со сметаной или мёдом.']::text[], 'https://www.iamcook.ru/showrecipe/36419', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
