insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-blinchiki-tvorog', 'Блинчики с творогом', 'Тонкие блинчики, свёрнутые с творогом и томлённые на масле', 'breakfast', array['breakfast','snack']::text[], 50, 60, 4, 2, 'cottage', array['выходные','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Начинку прогреть до горячего: в ней сырое яйцо. Диме 1–2 блинчика со сметаной', array['Яйцо взболтать с сахаром, солью и содой, влить стакан молока и размешать.','Всыпать муку и крахмал и размешать венчиком без комочков, затем понемногу влить остальное молоко и масло.','На хорошо прогретой сковороде испечь тонкие блинчики, выйдет около 15 штук.','Творог смешать с сахаром, щепоткой соли и вторым яйцом.','На каждый блинчик положить начинку, свернуть рулетиком и разрезать пополам.','Выложить в сковороду с кусочком сливочного масла, накрыть и томить на самом слабом огне 7 минут, перевернуть и подержать ещё 2 минуты.']::text[], 'https://www.iamcook.ru/showrecipe/6257', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
