insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-lenivye-hachapuri', 'Ленивые хачапури', 'Сырная лепёшка на сковороде за 20 минут, без теста и раскатки', 'breakfast', array['breakfast','snack']::text[], 15, 20, 4, 1, 'dairy', array['быстро','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме кусок из середины, без поджаристого края; соль в тесто не добавлять', array['Сыр натереть, зелёный лук мелко нарезать.','Смешать сыр с яйцами, сметаной и луком.','Добавить муку, соду и соль и перемешать до однородного густого теста.','Разогреть сковороду с растительным маслом и кусочком сливочного, выложить тесто и разровнять.','Печь на небольшом огне примерно по 5 минут с каждой стороны до румяной корочки.','Переложить на тарелку и нарезать на куски.']::text[], 'https://www.edimdoma.ru/retsepty/141636-lenivye-hachapuri', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
