insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-oladi-ovsyanye', 'Овсяные оладьи на кефире', 'Оладьи из овсяных хлопьев: сытные и мягкие, хороши со сметаной', 'breakfast', array['breakfast','snack']::text[], 20, 35, 3, 1, 'dairy', array['будни','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме испечь оладьи в духовке на бумаге: 200°, 12–15 минут, перевернуть на середине', array['Хлопья смолоть блендером в среднюю крошку, залить кефиром и оставить на 15 минут.','Вбить яйцо, влить 2 ст. л. масла и перемешать.','Муку смешать с сахаром, содой и разрыхлителем и соединить с овсяной массой: тесто выйдет густым.','Жарить ложкой на разогретом масле до румяности с двух сторон.','Подавать со сметаной, джемом или сгущёнкой.']::text[], 'https://www.edimdoma.ru/retsepty/78741-ovsyanye-oladi-na-kefire', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
