insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-oladi-grechka', 'Оладьи из гречневой каши', 'Вчерашняя гречка превращается в сладкие нежные оладьи без муки', 'breakfast', array['breakfast','snack']::text[], 25, 45, 4, 1, 'egg', array['будни','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме испечь оладьи в духовке на бумаге: 200°, 12–15 минут, перевернуть на середине', array['Гречку сварить заранее, можно с вечера, и остудить хотя бы до тёплой, чтобы не сварились яйца.','Смешать кашу с сахаром и яйцами.','Добавить соду и тёплое молоко и пробить всё погружным блендером до однородности.','Разогреть сковороду с маслом и выкладывать массу столовой ложкой.','Обжарить с двух сторон до корочки и выложить на бумажное полотенце.','Подавать со сметаной или вареньем.']::text[], 'https://www.iamcook.ru/showrecipe/24525', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
