insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-oladi-kukuruza', 'Кукурузные оладьи', 'Несладкие оладьи, где почти одна кукуруза: с зеленью и перцем', 'breakfast', array['breakfast','snack']::text[], 20, 25, 3, 1, 'none', array['быстро','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме испечь в духовке на бумаге: 200°, 12–15 минут; зёрна в его тесте слегка размять', array['Кукурузу откинуть на дуршлаг и дать жидкости стечь минут 5.','Зелень мелко порубить, болгарский перец нарезать мелким кубиком.','Смешать в миске кукурузу, зелень, перец, яйцо и кефир, посолить.','Добавлять муку по ложке, пока тесто не станет густым.','Жарить ложкой на разогретом масле 1–2 минуты, перевернуть и жарить ещё минуту.','Выложить на салфетку и подавать со сметаной, взрослым поперчить.']::text[], 'https://www.iamcook.ru/showrecipe/13957', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
