insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-oladi-tykva', 'Тыквенные оладьи', 'Тёртая тыква, яйцо и немного муки: оранжевые оладьи за 25 минут', 'breakfast', array['breakfast','snack']::text[], 20, 25, 4, 1, 'egg', array['быстро','детское','бюджетное']::text[], array['autumn','winter']::text[], '{}'::text[], 'adapt', 'Диме испечь оладьи в духовке на бумаге: 200°, 12–15 минут, перевернуть на середине', array['Тыкву натереть на средней тёрке, оставить на 10 минут и отжать лишний сок.','Яйца слегка взбить и добавить к тыкве.','Всыпать муку, соль и ванильный сахар и хорошо перемешать.','Выкладывать тесто ложкой на сковороду с небольшим количеством масла и жарить на среднем огне до румянца.','Перевернуть, дожарить и выложить на бумажное полотенце. Подавать со сметаной.']::text[], 'https://www.gastronom.ru/recipe/25537/oladi-iz-tykvy-bystro', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
