insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-smuzi-boul', 'Смузи-боул с клубникой и бананом', 'Густой ягодный смузи в тарелке: едят ложкой, как мороженое', 'breakfast', array['breakfast','snack']::text[], 10, 10, 2, 0, 'none', array['быстро','без плиты','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Диме полпорции, кунжут ему не сыпать', array['Банан очистить и нарезать, клубнику помыть и убрать хвостики. Пару ягод и кружков банана отложить для украшения.','Пробить банан с клубникой блендером в пюре.','Добавить хлопья и молоко и взбить на высокой скорости до густой однородной массы.','Переложить в глубокие тарелки, сверху разложить банан и ягоды, посыпать кунжутом.']::text[], 'https://www.iamcook.ru/showrecipe/22312', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
