insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-tosty-banan', 'Тосты с бананом и творожным сыром', 'Сладкие тосты за 10 минут: хрустящий хлеб, сливочный сыр и банан', 'breakfast', array['breakfast','snack']::text[], 10, 10, 4, 0, 'dairy', array['быстро','без плиты','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Диме ломтик помягче, без пересушенной корки', array['Батон нарезать ломтиками и подсушить в тостере или духовке.','Дать хлебу чуть остыть и намазать творожным сыром.','Банан нарезать кружками и разложить сверху.','Полить мёдом и сразу подавать, пока хлеб хрустит.']::text[], 'https://www.iamcook.ru/showrecipe/34080', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
