insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-maffiny-kabachok', 'Маффины с кабачком и сыром', 'Несладкие кексы с кабачком: печём с вечера, утром берём с собой', 'breakfast', array['breakfast','snack']::text[], 15, 45, 4, 2, 'egg', array['будни','духовка','детское','на 2–3 дня']::text[], array['summer','autumn']::text[], '{}'::text[], 'ok', 'Запечённые и мягкие — Диме как есть', array['Духовку разогреть до 180°. Кабачок и сыр натереть на крупной тёрке, из кабачка отжать сок.','Соединить кабачок и сыр, посолить и вбить яйца.','Добавить рубленую зелень, масло и молоко и перемешать.','Всыпать манку и муку с разрыхлителем: тесто должно быть как густая сметана.','Формочки смазать маслом и заполнить на 2/3.','Выпекать 25–30 минут до золотистой корочки, проверить лучинкой, дать остыть и вынуть.']::text[], 'https://1000.menu/cooking/21674-maffiny-s-kabachkom-i-syrom', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
