insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-paprikash-iz-kuricy', 'Паприкаш из курицы', 'Курица в сметанном соусе со сладкой паприкой, перцем и яблоком', 'main', array['dinner','lunch']::text[], 25, 35, 4, 2, 'poultry', array['будни']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить его порцию до соли, курицу нарезать мельче.', array['Лук нарезать полукольцами, перец — небольшими квадратиками, помидоры и яблоки — дольками, курицу — кубиками 2–3 см.','Обжарить курицу на половине масла около 5 минут до золотистого цвета, лучше в два захода, и переложить на тарелку.','На оставшемся масле 3 минуты жарить лук, добавить перец и готовить ещё пару минут.','Всыпать муку и паприку и прогреть, помешивая, 2 минуты. Добавить помидоры с яблоками и тушить 5–7 минут.','Вмешать сметану, посолить, вернуть курицу и томить под крышкой на слабом огне 2–3 минуты. Посыпать петрушкой.']::text[], 'https://www.gastronom.ru/recipe/3733/paprikash-s-kuricej', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
