insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kurinye-ruletiki-s-syrom', 'Куриные рулетики с сыром', 'Тонкие пласты филе с сырно-укропной начинкой, запечённые в сухарях', 'main', array['dinner','lunch']::text[], 25, 60, 4, 2, 'poultry', array['духовка','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Плавленый сыр и перец ему нельзя: свернуть ему рулетик только с твёрдым сыром, сметаной и укропом.', array['Филе слегка подморозить, чтобы легче резалось, и нарезать вдоль на тонкие пласты, по три из каждого.','Посолить, поперчить, посыпать паприкой, накрыть плёнкой и слегка отбить.','Для начинки натереть оба сыра, добавить рубленый укроп, чеснок через пресс и сметану, перемешать.','Намазать начинку на мясо, свернуть рулетами и обвалять в сухарях.','Выложить на смазанный маслом противень и запекать 30–40 минут при 190 °C.']::text[], 'https://www.gastronom.ru/recipe/51198/kurinye-ruletiki-s-syrom-v-duhovke', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
