insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-bulgur-s-kuricey-i-ovoshchami', 'Булгур с курицей и овощами', 'Курица, перец, морковь и булгур в одной сковороде — сразу с гарниром', 'main', array['dinner','lunch']::text[], 25, 40, 4, 2, 'poultry', array['будни','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить его порцию до соли, перца и приправ, курицу нарезать мельче.', array['Булгур промыть, залить 400 мл горячей воды, посолить и варить под крышкой на слабом огне около 15 минут, пока вода не впитается.','Перец нарезать небольшими кусочками, морковь — тонкими ломтиками, курицу — некрупными кубиками.','Морковь обжарить на масле 2–3 минуты, добавить перец и жарить ещё 3 минуты.','Положить курицу и готовить, помешивая, около 15 минут, пока мясо не побелеет и не дойдёт.','Добавить булгур, посолить, поперчить, приправить и перемешать. Прогреть пару минут.']::text[], 'https://1000.menu/cooking/29147-bulgur-s-kuricei', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
