insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kurica-celikom-s-yablokami', 'Курица, запечённая целиком с яблоками', 'Воскресная курица в горчичном маринаде с печёными яблоками; замариновать с утра', 'main', array['dinner','lunch']::text[], 15, 80, 4, 2, 'poultry', array['выходные','духовка','праздничное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Кожу с горчицей и перцем ему не давать: мясо снять с костей, нарезать мелко, дать с печёным яблоком.', array['Чеснок пропустить через пресс и смешать с горчицей, маслом, солью и перцем.','Курицу обсушить, натереть маринадом снаружи и внутри и оставить минимум на 2–3 часа, лучше на ночь в холодильнике.','Яблоки освободить от сердцевины, нарезать четвертинками и начинить ими курицу.','Уложить в рукав для запекания, проколоть его в нескольких местах и запекать около часа при 200 °C.','Разрезать на порции и подать вместе с печёными яблоками.']::text[], 'https://1000.menu/cooking/42385-kurica-v-duxovke-celikom-s-yablokami-farshirovannaya', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
