insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kartofelnye-lodochki-s-kurinym-farshem', 'Картофельные лодочки с куриным фаршем', 'Половинки картошки с куриным фаршем под сметаной и сыром — дети едят руками', 'main', array['dinner','lunch']::text[], 30, 50, 4, 1, 'poultry', array['духовка','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его лодочку не перчить, фарш для неё солить по минимуму.', array['Картофель очистить, разрезать вдоль пополам и отварить в подсоленной воде около 15 минут: он должен стать мягким, но не развалиться. Остудить.','Филе прокрутить вместе с луком через мясорубку, посолить и поперчить.','Чайной ложкой вынуть из половинок мякоть, оставив стенки 5–7 мм.','Наполнить лодочки фаршем, смазать сметаной, слегка поперчить и посыпать тёртым сыром.','Выложить в смазанную маслом форму и запекать около 20 минут при 200 °C. Посыпать укропом.']::text[], 'https://1000.menu/cooking/19512-kartofelnye-lodochki-v-duxovke-s-nachinkoi-farshem', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
