insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kurinye-zrazy-s-yaycom', 'Куриные зразы с яйцом и луком', 'Котлетки из куриного филе с яйцом и зелёным луком внутри, допечённые в духовке', 'main', array['dinner','lunch']::text[], 40, 75, 4, 2, 'poultry', array['духовка','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его зразы не обжаривать: сразу выложить в форму на пергамент и запекать те же 30–35 минут.', array['Филе измельчить блендером в фарш, вбить одно яйцо, добавить муку и половину соли и вымесить.','Второе яйцо сварить вкрутую, мелко порубить и смешать с нашинкованным зелёным луком и щепоткой соли.','Взять немного фарша, расплющить в лепёшку на ладони, положить в середину ложку начинки и защипнуть края.','Обвалять зразы в сухарях и быстро обжарить на сильном огне с двух сторон до корочки.','Переложить в форму и допекать 30–35 минут при 180 °C.']::text[], 'https://www.iamcook.ru/showrecipe/25487', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
