insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-indeyka-s-chernoslivom', 'Индейка с черносливом в духовке', 'Кусочки индейки с черносливом и мёдом, запечённые в духовке', 'main', array['dinner','lunch']::text[], 15, 110, 4, 2, 'poultry', array['духовка']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить его кусочки до перца, мясо и чернослив нарезать мелко.', array['Индейку нарезать средними кусками. Чернослив промыть и проверить, не осталось ли косточек.','Крупные зубчики чеснока разрезать вдоль на 2–3 части, мелкие оставить целыми.','Смешать индейку с черносливом, маслом, мёдом, солью и перцем и оставить на час при комнатной температуре или на 2 часа в холодильнике.','Выложить в форму, сверху разложить чеснок и запекать около 40 минут при 180 °C, поливая соком со дна формы.']::text[], 'https://1000.menu/cooking/44437-indeika-s-chernoslivom-v-duxovke', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
