insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kurica-s-meksikanskoy-smesyu', 'Курица с мексиканской смесью', 'Бёдра и замороженные овощи в одной форме — овощи резать не нужно', 'main', array['dinner','lunch']::text[], 10, 120, 4, 2, 'poultry', array['духовка','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Майонез ему нельзя: одно бедро отложить до маринада и запечь рядом с солью. Кожу снять, мясо снять с кости.', array['Смешать майонез, кетчуп, чеснок, соль и перец.','Бёдра обсушить, обмазать маринадом, накрыть плёнкой и оставить на 1–2 часа.','Выложить курицу в форму, рядом высыпать смесь, не размораживая, и слегка её посолить.','Запекать 30–40 минут при 200 °C, пока сок при проколе не станет прозрачным.']::text[], 'https://1000.menu/cooking/26908-meksikanskaya-smes-s-kuricei', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
