insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kurica-s-brokkoli-pod-syrom', 'Курица с брокколи под сыром', 'Кубики филе и брокколи, запечённые в сливках под сырной корочкой', 'main', array['dinner','lunch']::text[], 20, 40, 4, 1, 'poultry', array['будни','духовка','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его порцию не перчить, курицу и соцветия нарезать мельче.', array['Брокколи разобрать на соцветия и отварить 3–4 минуты; замороженную можно не варить.','Филе нарезать мелкими кубиками и обжарить на небольшом количестве масла, пока не побелеет.','Выложить курицу в форму, сверху брокколи, посолить и поперчить.','Залить сливками, посыпать тёртым сыром и запекать 20–25 минут при 180 °C.']::text[], 'https://1000.menu/cooking/40411-brokkoli-s-kuricei-v-duxovke', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
