insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kurinoe-file-s-kabachkami', 'Куриное филе с кабачками на сковороде', 'Курица с кабачком, перцем и черри за полчаса в одной сковороде', 'main', array['dinner','lunch']::text[], 15, 35, 4, 1, 'poultry', array['будни']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Чили не класть, его порцию отложить до перца, курицу и овощи нарезать мельче.', array['Кабачок нарезать кубиками (у зрелого срезать кожицу и убрать семена), перец — небольшими кусочками, черри — четвертинками, чеснок измельчить.','Филе обсушить, нарезать небольшими кубиками и посыпать специями.','Разогреть масло в толстостенной сковороде и выложить курицу вместе со всеми овощами.','Посолить и жарить на среднем огне без крышки 20–25 минут, периодически помешивая.','Поперчить и посыпать зеленью.']::text[], 'https://1000.menu/cooking/54206-kurinoe-file-s-kabachkami-na-skovorode', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
