insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-myasnoy-rulet-s-yaycom', 'Мясной рулет с яйцом', 'Рулет из двух видов фарша с варёными яйцами внутри — горячим и на бутерброды', 'main', array['dinner','lunch']::text[], 30, 75, 4, 3, 'red-meat', array['духовка','детское','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Фарш и верх рулета не перчить — взрослым поперчить в тарелке; солить умеренно.', array['Яйца опустить в кипящую воду, после нового закипания через минуту выключить огонь и оставить под крышкой на 10 минут. Остудить и очистить.','Лук и чеснок мелко нарезать, обжарить на масле 7 минут, посыпать паприкой и остудить.','Соединить оба фарша, жареный лук и тёртый кабачок, посолить, поперчить и хорошо вымесить. Крахмал развести 3 ст. л. холодной воды и тоже вмешать.','Форму смазать маслом и присыпать сухарями. Выложить половину фарша, в ряд уложить яйца, закрыть остальным фаршем и плотно прижать.','Посыпать сухарями, накрыть фольгой и запекать 40 минут при 180 °C, затем ещё 5–7 минут без фольги.']::text[], 'https://www.gastronom.ru/recipe/34120/myasnoj-rulet-s-yajcom-v-duhovke', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
