insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-musaka-s-kartoshkoy', 'Мусака с картошкой', 'Слои картошки, мясного фарша с сыром и жареных баклажанов в томате', 'main', array['dinner','lunch']::text[], 45, 90, 4, 2, 'red-meat', array['выходные','духовка']::text[], array['summer','autumn']::text[], '{}'::text[], 'adapt', 'Фарш не перчить — взрослым поперчить в тарелке. Ему кусок без подгоревшего верха, нарезать мелко.', array['Баклажаны нарезать вдоль пластинами 1 см, посолить на 15 минут, слить сок, промыть и обсушить.','Обжарить пластины порциями на масле с двух сторон до золотистого цвета.','В другой сковороде минуту прогреть рубленый чеснок, добавить фарш и жарить около 15 минут, разбивая комочки. Посолить и поперчить.','Картофель нарезать тонкими кружочками и выложить внахлёст на дно формы. Если боитесь, что не пропечётся, сначала отварить его 4–5 минут.','Сверху выложить половину фарша, половину тёртого сыра и часть томатов, повторить слой фарша с сыром и залить остатком томатов.','Закрыть баклажанами, сверху разложить кружочки помидоров и запекать около 25 минут при 190 °C, пока картофель не станет мягким.']::text[], 'https://1000.menu/cooking/43890-musaka-s-kartofelem-i-baklajanami', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
