insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-lodochki-iz-kabachkov-s-farshem', 'Лодочки из кабачков с фаршем', 'Половинки молодых кабачков с мясной начинкой, помидором и сыром', 'main', array['dinner','lunch']::text[], 35, 80, 4, 2, 'red-meat', array['духовка','детское']::text[], array['summer','autumn']::text[], '{}'::text[], 'adapt', 'Начинку для его лодочки не перчить, при подаче вынуть из кожуры и размять.', array['Кабачки разрезать вдоль и ложкой выбрать мякоть, оставив стенки. Смазать лодочки маслом изнутри и запечь кожурой вверх 15–20 минут при 180 °C.','Лук и чеснок мелко нарезать и обжарить до мягкости, добавить 80 г мякоти кабачка кубиками и жарить ещё 5 минут.','Обжарить фарш около 10 минут, разбивая комочки, и остудить.','Смешать фарш, овощи, 50 г тёртого сыра и рубленую зелень, посолить и поперчить.','Слегка посолить лодочки изнутри, наполнить начинкой и разложить сверху полукружья помидоров.','Запекать 30–40 минут при 180 °C до мягкости кабачка. Посыпать остальным сыром и подержать в духовке ещё 1–2 минуты.']::text[], 'https://www.iamcook.ru/showrecipe/12973', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
