insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-svinye-rebryshki-s-kartoshkoy', 'Свиные рёбрышки с картошкой', 'Рёбрышки и картошка в рукаве с чесноком — всё печётся само', 'main', array['dinner','lunch']::text[], 15, 105, 4, 2, 'red-meat', array['выходные','духовка']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Мясо снять с кости, жир срезать, нарезать мелко; ему ребро без перца, посолить отдельно.', array['Рёбрышки обсушить, разрубить на порционные куски и натереть солью и перцем.','Картофель очистить, нарезать крупно, сложить в рукав для запекания и слегка посолить.','Добавить рёбрышки и очищенные зубчики чеснока, рукав завязать и проколоть в нескольких местах.','Запекать 1–1,5 часа при 180 °C, пока мясо и картошка не станут мягкими.']::text[], 'https://1000.menu/cooking/40381-svinye-rebryshki-s-kartoshkoi-v-duxovke', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
