insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-svinina-zapechennaya-kuskom', 'Свинина, запечённая куском', 'Домашняя буженина в фольге с чесноком: горячим на ужин, холодным на бутерброды', 'main', array['dinner','lunch']::text[], 15, 110, 4, 3, 'red-meat', array['выходные','духовка','на 2–3 дня','праздничное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Ему кусочек из середины, без чесночно-перечной корочки, нарезать мелко.', array['Духовку разогреть до 240 °C. Чеснок мелко нарезать и смешать с солью и перцем.','Мясо обсушить, срезать лишнее и натереть смесью со всех сторон, вдавливая её в мякоть.','Плотно завернуть в фольгу, чтобы сок не вытекал; большой кусок — в два слоя.','Поставить в духовку, снизить нагрев до 200 °C и запекать 60–80 минут: примерно 40 минут на килограмм плюс 20. Внутри куска должно быть 78–80 °C.','Дать остыть в фольге, нарезать ломтями и полить соком из фольги.']::text[], 'https://1000.menu/cooking/11690-svinina-zapechennaya-kuskom-v-folge', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
