insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-azu-po-tatarski', 'Азу по-татарски', 'Говядина с солёными огурцами в томате и жареной картошкой', 'main', array['dinner','lunch']::text[], 60, 90, 4, 2, 'red-meat', array['выходные']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Ему отложить мясо с луком до огурцов, чеснока и перца и дотушить под крышкой; картошку дать отварную.', array['Картофель нарезать брусочками 1×4 см, обсушить и обжарить порциями в большом количестве масла до румяности. Откинуть на сито, не солить.','Говядину нарезать поперёк волокон ломтиками 1 см, а затем такими же брусочками. Лук нарезать перьями, огурцы — соломкой.','На сильно разогретой сковороде обжарить мясо, не трогая, пока не появится корочка, затем перемешать и обжарить с другой стороны.','Влить 200 мл кипятка и тушить на среднем огне, пока вода не выпарится. Добавить немного масла и лук и жарить до золотистого цвета.','Вмешать томатную пасту и прогреть 2–3 минуты. Положить огурцы и чеснок, поперчить, влить 150–200 мл кипятка, добавить сахар и тушить 5–7 минут.','Добавить картофель, аккуратно перемешать, прогреть 2–3 минуты и посыпать петрушкой.']::text[], 'https://www.gastronom.ru/recipe/58347/azu-po-tatarski-iz-govyadiny-s-solenymi-ogurcami', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
