insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-lyulya-kebab-v-duhovke', 'Люля-кебаб в духовке', 'Говяжий фарш с луком и зеленью на шпажках — шашлык без мангала', 'main', array['dinner','lunch']::text[], 25, 180, 4, 2, 'red-meat', array['выходные','духовка']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить ему часть фарша до перца и специй и вылепить отдельную колбаску.', array['Лук натереть на мелкой тёрке, откинуть на сито и слегка отжать.','Смешать фарш с луком, специями, солью и рубленой зеленью и хорошо вымесить.','Накрыть плёнкой и убрать в холодильник минимум на 2 часа. За 20 минут до конца замочить деревянные шпажки в холодной воде и разогреть духовку до 250 °C.','Разделить фарш на 4 части и вылепить на шпажках вытянутые колбаски толщиной около 4 см.','Запекать около 15 минут, перевернуть и печь ещё 15 минут.']::text[], 'https://1000.menu/cooking/15557-lulya-kebab-iz-govyadiny', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
