insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-perlovka-s-myasom', 'Перловка с мясом', 'Перловая каша со свининой, луком и морковью на два дня; крупу замочить с вечера', 'main', array['dinner','lunch']::text[], 25, 90, 4, 3, 'red-meat', array['бюджетное','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить его порцию до соли, мясо нарезать мелко, лавровый лист вынуть.', array['Перловку промыть и замочить в холодной воде на несколько часов или на ночь.','Промыть ещё раз, опустить в кипящую воду и варить на слабом огне около часа до мягкости. Слегка посолить и откинуть на дуршлаг.','Пока варится крупа, свинину нарезать небольшими кусочками и обжарить на масле 5–7 минут до румяности.','Добавить мелко нарезанный лук и тёртую морковь и жарить ещё 2–3 минуты.','Залить стаканом горячей воды, положить лавровый лист и тушить на слабом огне 30–40 минут до мягкости мяса. Посолить.','Смешать мясо с перловкой и прогреть пару минут.']::text[], 'https://1000.menu/cooking/72456-perlovaya-kasha-s-myasom', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
