insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-svinina-v-kislo-sladkom-souse', 'Свинина в кисло-сладком соусе', 'Свинина с морковью и перцем в томатно-соевом соусе, как в китайском кафе', 'main', array['dinner','lunch']::text[], 30, 45, 4, 1, 'red-meat', array['будни','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Соевый соус и уксус ему нельзя: несколько кусочков свинины без маринада потушить с частью овощей в воде под крышкой.', array['Свинину нарезать некрупными брусочками, смешать с половиной крахмала, 2 ст. л. соевого соуса и половиной воды и оставить на 15–20 минут.','Тем временем морковь натереть тонкой соломкой, лук нарезать полукольцами, перец — тонкими полосками.','Для соуса смешать томатную пасту, оставшийся соевый соус, уксус, имбирь, чеснок через пресс, сахар, остаток крахмала и воды.','Обжарить свинину на масле в два захода до готовности и румяности и переложить в тарелку.','На той же сковороде 3–5 минут жарить овощи на огне чуть выше среднего.','Вернуть мясо, влить соус, перемешать и подержать под крышкой на минимальном огне 3–5 минут. Посыпать кунжутом и зеленью.']::text[], 'https://1000.menu/cooking/23232-svinina-s-ovoshchami-v-kislo-sladkom-souse', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
