insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-bliny-s-myasom', 'Блины с мясом', 'Тонкие блины с жареным фаршем и луком — на ужин и в морозилку про запас', 'main', array['dinner','lunch']::text[], 60, 75, 4, 2, 'red-meat', array['выходные','детское','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Начинку для его блинов отложить до перца, блины нарезать, дать со сметаной.', array['Яйца растереть с сахаром, влить часть масла и молоко и перемешать.','Всыпать просеянную муку с содой и солью и размешать до гладкого теста без комочков.','Испечь тонкие блины на горячей сковороде, смазав её маслом перед первым блином. Складывать стопкой под крышку, чтобы не подсохли.','Свинину прокрутить в фарш и обжарить на масле 3–5 минут.','Добавить мелко нарезанный лук и жарить ещё около 15 минут на среднем огне до золотистого цвета. Посолить и поперчить.','На край каждого блина положить 1–2 ложки начинки, подвернуть края и свернуть рулетиком. Подавать горячими со сметаной.']::text[], 'https://1000.menu/cooking/16950-farshirovannye-bliny-s-myasnym-farshem', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
