insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-grechaniki-v-smetanno-tomatnom-souse', 'Гречаники в сметанно-томатном соусе', 'Котлеты из фарша с гречкой, томлённые в соусе со сметаной и томатом', 'main', array['dinner','lunch']::text[], 35, 75, 4, 2, 'red-meat', array['детское','бюджетное','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его гречаники не обжаривать, а сразу положить в соус и томить под крышкой; фарш для него не перчить.', array['Отварить гречку и остудить.','Половину лука прокрутить с мясом или смешать с готовым фаршем, добавить гречку, яйца, соль и перец и вымесить.','Слепить котлеты, обвалять в муке и обжарить на масле до золотистого цвета.','В другой сковороде обжарить оставшийся мелко нарезанный лук, добавить сметану и томаты и прогреть.','Уложить гречаники в соус и томить под крышкой 25 минут.']::text[], 'https://1000.menu/cooking/20013-grechaniki-s-sousom', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
