insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-pasta-s-semgoy-v-slivochnom-souse', 'Паста с сёмгой в сливочном соусе', 'Кусочки сёмги в сливках с макаронами и тёртым сыром за 25 минут', 'main', array['dinner','lunch']::text[], 25, 25, 4, 1, 'fish', array['быстро','будни','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его порцию не перчить, рыбу проверить на кости, макароны нарезать.', array['Поставить вариться макароны в подсоленной воде по инструкции на пачке.','Сёмгу обсушить и нарезать кубиками. В сковороде прогреть масло с зубчиком чеснока и вынуть чеснок, как только он зарумянится.','Обжаривать рыбу в ароматном масле около 5 минут, переворачивая. Посолить, поперчить и посыпать травами.','Влить сливки до половины высоты кусочков и тушить на слабом огне 7–10 минут.','Разложить макароны по тарелкам, сверху рыбу с соусом и посыпать тёртым сыром.']::text[], 'https://1000.menu/cooking/38590-pasta-s-semgoi-v-slivochnom-souse', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
