insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-rybnye-palochki', 'Рыбные палочки', 'Домашние палочки из филе в хрустящей панировке — не хуже магазинных', 'main', array['dinner','lunch']::text[], 30, 40, 4, 1, 'fish', array['будни','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его палочки не жарить: выложить на пергамент и запечь 15 минут при 200 °C.', array['Филе обсушить, нарезать брусочками одного размера и подержать 5 минут на бумажном полотенце.','Яйца взбить. Муку и яйца посолить и поперчить, сухари насыпать в отдельную тарелку.','Обвалять брусочки в муке, обмакнуть в яйцо и запанировать в сухарях. Если есть время, убрать на полчаса в холодильник.','Жарить в разогретом масле по 2,5–3 минуты с каждой стороны до румяной корочки.','Подать с тонкими лентами моркови и огурца, нарезанными овощечисткой.']::text[], 'https://1000.menu/cooking/17490-rybno-kartofelnye-palochki', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
