insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-rybnoe-sufle-kak-v-sadike', 'Рыбное суфле, как в садике', 'Нежное суфле из отварного минтая с молочным соусом — без костей и жарки', 'main', array['dinner','lunch']::text[], 30, 90, 4, 2, 'fish', array['духовка','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Подходит как есть. Рыбу особенно тщательно перебрать от костей, солить умеренно.', array['Минтай очистить и отварить в подсоленной воде около 25 минут. Вынуть и отделить мясо от костей и кожи.','Муку подсушить в сухой кастрюльке до лёгкого золотистого цвета, влить молоко и, помешивая венчиком, варить 3–5 минут до загустения.','Отделить белки от желтков и убрать белки в холодильник.','Пробить блендером рыбу, соус и желтки до однородности и слегка посолить.','Взбить холодные белки в устойчивую пену и аккуратно вмешать в рыбную массу.','Выложить в смазанную маслом форму и запекать 30–40 минут при 180 °C до золотистой корочки.']::text[], 'https://1000.menu/cooking/42014-rybnoe-sufle-v-duxovke-kak-v-detskom-sadu', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
