insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kotlety-iz-gorbushi', 'Котлеты из горбуши', 'Сочные котлеты из недорогой красной рыбы с батоном на молоке', 'main', array['dinner','lunch']::text[], 30, 40, 4, 2, 'fish', array['будни','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его котлеты не жарить: запечь на пергаменте 20 минут при 190 °C или приготовить на пару.', array['Отделить мякоть рыбы от костей и кожи. Батон замочить в молоке.','Прокрутить через мясорубку рыбу, лук и отжатый батон.','Добавить яйцо, манку и соль, перемешать и хорошо отбить фарш о дно миски.','Слепить котлеты, обвалять в сухарях и обжарить на масле с двух сторон до румяной корочки.','Сложить в кастрюлю и подержать несколько минут под крышкой, чтобы котлеты допарились.']::text[], 'https://1000.menu/cooking/37764-rybnye-kotlety-iz-gorbushi', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
