insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-skumbriya-s-kartoshkoy-v-duhovke', 'Скумбрия с картошкой в духовке', 'Целая скумбрия на подушке из картошки с луком — рыба и гарнир в одной форме', 'main', array['dinner','lunch']::text[], 20, 75, 4, 1, 'fish', array['духовка','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его кусочек снять с хребта, убрать кожу и все кости.', array['Скумбрию выпотрошить, удалить голову и плавники, промыть и натереть солью и перцем снаружи и внутри.','Картофель нарезать дольками, лук — полукольцами.','Выложить картофель в форму, полить маслом, посолить, поперчить и разложить сверху лук.','Уложить рыбу на овощи, влить кипяток и запекать при 200 °C 25–50 минут, пока картофель не станет мягким.']::text[], 'https://1000.menu/cooking/33015-skumbriya-zapechennaya-s-kartoshkoi-v-duxovke', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
