insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-rybnye-kotlety-s-tvorogom', 'Рыбные котлеты с творогом', 'Мягкие котлеты из хека с творогом, запечённые без жарки', 'main', array['dinner','lunch']::text[], 25, 60, 4, 2, 'fish', array['духовка','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Фарш не перчить — взрослым поперчить в тарелке.', array['Филе дважды пропустить через мясорубку, чтобы не осталось мелких косточек.','Лук мелко порубить и обжарить на капле масла до золотистого цвета, добавить к фаршу.','Вмешать творог, яйца, соль, перец и манку и оставить на 20 минут, чтобы манка набухла.','Мокрыми руками слепить котлеты, выложить на противень и налить немного воды между ними.','Запекать 20 минут при 200 °C.']::text[], 'https://1000.menu/cooking/36699-rybnye-kotlety-s-tvorogom-v-duxovke', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
