insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-mintay-tushenyy-v-moloke', 'Минтай, тушённый в молоке', 'Минтай с луком в молочном соусе, как в детском саду, за полчаса', 'main', array['dinner','lunch']::text[], 25, 30, 4, 2, 'fish', array['быстро','будни','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его кусочки не обжаривать: положить сразу в молочный соус и тушить 10–12 минут, перед подачей убрать кости.', array['Минтай разморозить, обсушить, нарезать небольшими кусками и посолить.','Обжарить рыбу в разогретом масле на сильном огне 5–7 минут до корочки.','Высыпать сверху лук тонкими полукольцами, перевернуть рыбу так, чтобы лук оказался между кусками, и жарить ещё 5–7 минут на огне потише.','Муку подсушить на сухой сковороде, развести ложкой молока без комочков и влить остальное молоко.','Залить рыбу молочным соусом, добавить соль и лавровый лист, довести до кипения и тушить 7–10 минут.']::text[], 'https://1000.menu/cooking/30676-mintai-tushenyi-v-moloke-na-skovorode', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
