insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-hek-tushenyy-v-smetane', 'Хек, тушённый в сметане', 'Хек на подушке из лука и моркови, тушённый под сметаной', 'main', array['dinner','lunch']::text[], 10, 40, 4, 2, 'fish', array['будни','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его кусочек не перчить, перед подачей разобрать и убрать все кости.', array['Лук нарезать, морковь натереть и обжарить на масле до мягкости на среднем огне.','Хек почистить, промыть и нарезать кусками.','Выложить рыбу на овощи, посолить, поперчить и полить сметаной.','Накрыть крышкой и тушить на слабом огне 25–30 минут.']::text[], 'https://www.iamcook.ru/showrecipe/24822', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
