insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-steyki-gorbushi-na-skovorode', 'Стейки горбуши на сковороде', 'Красная рыба в чесночно-лимонном маринаде: жарится 15 минут без лишнего масла', 'main', array['dinner','lunch']::text[], 15, 35, 4, 1, 'fish', array['будни']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его кусочек не обжаривать, а сразу потушить под крышкой с ложкой воды; снять кожу и выбрать все кости.', array['Стейки очистить от чешуи, промыть и досуха обсушить полотенцем.','Смешать чеснок через пресс, соль, лимонный сок и масло, обмазать рыбу и дать немного постоять.','Выложить стейки на разогретую сухую сковороду — масла из маринада хватит — и жарить без крышки 5–10 минут до золотистой корочки.','Перевернуть, накрыть крышкой и довести до готовности за 5–7 минут. Подавать сразу.']::text[], 'https://1000.menu/cooking/35824-steik-gorbushi-na-skovorode', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
