insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kartofelnye-gnezda-s-yaycom', 'Картофельные гнёзда с яйцом', 'Гнёздышки из тёртой картошки с сыром и запечённым яйцом внутри', 'main', array['dinner','lunch']::text[], 25, 75, 4, 1, 'egg', array['духовка','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его гнездо не перчить и допечь до плотного желтка.', array['Картофель отварить в мундире в подсоленной воде, остудить, очистить и натереть на крупной тёрке.','Смешать картофель с большей частью сыра и ложкой масла, посолить и поперчить.','Смазать формочки для кексов маслом, разложить картофель и прижать к дну и стенкам, чтобы получились гнёзда.','Запекать 15 минут при 220 °C, пока края не подрумянятся.','Снизить нагрев до 175 °C, разбить в каждое гнездо по яйцу, слегка посолить и посыпать остатком сыра.','Запекать ещё 13–15 минут, пока белок полностью не схватится. Вынуть, проведя ножом по краю, и посыпать петрушкой.']::text[], 'https://www.gastronom.ru/recipe/30334/video-recipe-kartofelnye-gnezda-s-yajcom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
