insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kapustnaya-zapekanka-s-syrom', 'Капустная запеканка с сыром', 'Тушёная капуста с морковью под яйцом и сырной корочкой — дёшево и сытно', 'main', array['dinner','lunch']::text[], 25, 45, 4, 2, 'egg', array['будни','духовка','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Капусту не перчить — взрослым поперчить в тарелке; солить умеренно.', array['Капусту тонко нашинковать, морковь натереть на крупной тёрке.','Тушить капусту с морковью на масле, помешивая; в середине посолить и поперчить. Немного остудить.','Взбить яйца вилкой и вмешать в капусту.','Выложить в смазанную маслом форму, разровнять и посыпать тёртым сыром.','Запекать около 20 минут при 180 °C, пока сыр не расплавится.']::text[], 'https://1000.menu/cooking/2522-zapekanka-iz-kapustj', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
