insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-vareniki-s-tvorogom', 'Вареники с творогом', 'Мягкое тесто на воде и творожная начинка — лепим с детьми, лишние в морозилку', 'main', array['dinner','lunch']::text[], 50, 80, 4, 1, 'cottage', array['выходные','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Подходит: варёное тесто и творог. Вареники ему разрезать.', array['В тёплую воду вбить яйцо, добавить соль и взболтать вилкой.','Подсыпать муку по стакану и замесить мягкое гладкое тесто, не перебивая муку. Накрыть полотенцем на 30 минут.','Для начинки размять творог с сахаром и щепоткой соли.','Тесто разделить на три части, раскатать каждую колбаской, нарезать кусочками и раскатать их в кружки.','Положить на кружок ложку начинки и плотно слепить края.','Варить в большой кастрюле подсоленной кипящей воды: после всплытия ещё пару минут. Вынуть шумовкой и подать со сметаной.']::text[], 'https://1000.menu/cooking/51043-klassicheskie-vareniki-s-tvorogom', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
