insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-lobio-iz-konservirovannoy-fasoli', 'Лобио из консервированной фасоли', 'Красная фасоль с луком, орехами и кинзой — грузинское блюдо за 40 минут', 'main', array['dinner','lunch']::text[], 20, 40, 4, 3, 'legume', array['будни','постное','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Ему отложить фасоль с луком до заправки (уксус, чеснок, перец нельзя) и размять, орехи только молотые. Бобовые — не чаще 2–3 раз в неделю.', array['Орехи подсушить на сухой сковороде до запаха, остудить и мелко порубить.','Лук нарезать полосками и обжарить на 3 ст. л. масла до мягкости, добавить паприку и перец.','Фасоль откинуть, сохранив жидкость, и прогреть с луком 2–3 минуты.','Влить жидкость из банки и тушить 20–25 минут, помешивая, пока она почти не выпарится; если выкипит раньше, подлить кипятка.','Смешать орехи, рубленую кинзу, тёртый чеснок, остаток масла, уксус, хмели-сунели и соль.','Добавить заправку и сахар к фасоли, перемешать и потушить ещё 2–3 минуты.']::text[], 'https://1000.menu/cooking/36568-lobio-iz-konservirovannoi-fasoli', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
