insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kotlety-iz-krasnoy-chechevicy', 'Котлеты из красной чечевицы', 'Постные котлеты из чечевицы с морковью и укропом — дешевле мясных', 'main', array['dinner','lunch']::text[], 30, 55, 4, 2, 'legume', array['постное','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его котлеты не жарить: запечь на пергаменте 20 минут при 200 °C. Бобовые — не чаще 2–3 раз в неделю.', array['Чечевицу промыть, залить водой 1:2, довести до кипения и варить на слабом огне 15–20 минут, пока вода не впитается и крупа не разварится. Размять и остудить.','Лук мелко нарезать и обжарить на масле до полуготовности, добавить морковь, натёртую на мелкой тёрке, и жарить до мягкости. Остудить.','Соединить чечевицу, овощи, паприку, рубленый укроп, муку и соль, перемешать и оставить на 15 минут.','Влажными руками слепить котлетки и обвалять в сухарях.','Обжарить на умеренном огне с двух сторон до румяной корочки.']::text[], 'https://1000.menu/cooking/90850-kotlety-iz-krasnoi-chechevicy-postnye', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
