insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-nut-tushenyy-s-ovoshchami', 'Нут, тушённый с овощами', 'Нут в томате с луком и морковью, постное и на три дня; нут замочить с вечера', 'main', array['dinner','lunch']::text[], 20, 90, 4, 3, 'legume', array['постное','бюджетное','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить его порцию до соли и перца, нут размять вилкой. Бобовые — не чаще 2–3 раз в неделю.', array['Нут залить водой на 2 см выше уровня и замочить на 8 часов.','Долить ещё стакан воды и варить около часа до мягкости.','Лук нарезать мелким кубиком, морковь натереть на крупной тёрке и обжарить на масле до мягкости.','Добавить протёртые томаты, сахар, соль и перец и готовить 5 минут.','Выложить нут, перемешать и тушить под крышкой около 20 минут.']::text[], 'https://1000.menu/cooking/43350-nut-tushenyi-s-ovoshchami', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
