insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-rizotto-s-tykvoy', 'Ризотто с тыквой', 'Сливочный рис с запечённой тыквой и пармезаном — оранжевый осенний ужин', 'main', array['dinner','lunch']::text[], 30, 40, 4, 1, 'dairy', array['будни','детское']::text[], array['autumn','winter']::text[], '{}'::text[], 'adapt', 'Отложить его порцию до перца; солить осторожно — пармезан солёный.', array['Тыкву нарезать мелким кубиком, сбрызнуть маслом, посолить, посыпать травами и запекать около 20 минут при 190 °C.','Лук и чеснок мелко нарезать и обжарить на оливковом масле 5–7 минут до мягкости.','Всыпать рис и жарить с луком 3–4 минуты, пока зёрна не станут прозрачными.','Вливать горячий бульон по половнику, помешивая, и каждый раз ждать, пока он впитается.','Когда рис станет мягким снаружи и чуть плотным внутри, добавить тыкву и сливочное масло и готовить ещё пару минут.','Снять с огня, вмешать тёртый пармезан, посолить и поперчить.']::text[], 'https://www.iamcook.ru/showrecipe/13157', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
