insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-tushenaya-kapusta-s-kartoshkoy', 'Тушёная капуста с картошкой', 'Капуста с картошкой и томатом в одной сковороде — постно, дёшево и сытно', 'main', array['dinner','lunch']::text[], 15, 45, 4, 2, 'none', array['будни','постное','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить его порцию до соли и перца, картошку размять.', array['Лук нарезать мелким кубиком, морковь натереть и обжарить на масле 3–5 минут до мягкости.','Капусту тонко нашинковать, добавить к овощам и тушить под крышкой на небольшом огне около 20 минут.','Картофель нарезать ломтиками среднего размера, добавить в сковороду, посолить и поперчить.','Тушить под крышкой ещё 15–20 минут до мягкости картошки, при необходимости подлить немного воды.','Вмешать томатную пасту и подержать на огне ещё 5 минут.']::text[], 'https://1000.menu/cooking/42804-tushenaya-kapusta-s-kartoshkoi-na-skovorode', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
