insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-baklazhany-s-pomidorami-i-syrom', 'Баклажаны с помидорами и сыром', 'Баклажаны, помидоры и сулугуни внахлёст, запечённые с чесноком и базиликом', 'main', array['dinner','lunch']::text[], 15, 40, 4, 1, 'dairy', array['будни','духовка']::text[], array['summer','autumn']::text[], '{}'::text[], 'adapt', 'Сулугуни солёный: его порцию не солить и не перчить, кожицу баклажана снять.', array['Баклажаны нарезать кружочками толщиной 0,5 см; если горчат, посолить на 15 минут и промыть.','Помидоры нарезать тонкими кружочками, чеснок — крупно, сыр — ломтиками.','Выложить в смазанную форму внахлёст, чередуя баклажаны, помидоры и сыр, и разбросать чеснок.','Полить маслом, посолить, поперчить и посыпать травами.','Запекать около 20 минут при 230 °C, дать постоять 10–15 минут и посыпать рубленым базиликом и петрушкой.']::text[], 'https://1000.menu/cooking/662-letnyaya-ovoshchnaya-zapekanka', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
