insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-zapekanka-mannaya', 'Манная запеканка как в садике', 'Запеканка из манной каши: дети едят её охотнее, чем саму кашу', 'snack', array['breakfast','snack']::text[], 20, 50, 3, 2, 'dairy', array['духовка','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Запеканка из садиковского меню, малышу как есть', array['Молоко с водой довести до кипения и, помешивая, тонкой струйкой всыпать манку.','Варить на слабом огне, пока каша не начнёт густеть, всыпать сахар и уварить до очень густой.','Остудить кашу до тёплой, чтобы яйцо не свернулось, и вмешать взбитое яйцо. Духовку разогреть до 180°.','Форму смазать маслом, присыпать манкой, выложить массу и разровнять, сверху смазать сметаной.','Запекать около 30 минут; если верх румянится слишком быстро, накрыть фольгой.','Перед нарезкой полностью остудить, тогда кусочки держат форму. Подать с вареньем или ягодным соусом.']::text[], 'https://www.iamcook.ru/showrecipe/16478', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
