insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-sufle-tvorozhnoe', 'Творожное суфле с яблоками', 'Воздушное суфле из творога на взбитых белках, с кусочками яблока', 'snack', array['breakfast','snack']::text[], 20, 60, 4, 2, 'cottage', array['духовка','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Творожное блюдо, малышу как есть; сахар можно убавить', array['Духовку разогреть до 180°. Яйца разделить на белки и желтки.','Желтки взбить с половиной сахара до светлой массы, добавить творог и пробить блендером до гладкости.','Белки взбить в чистой сухой миске, всыпать остальной сахар и взбивать до устойчивых пиков.','Яблоки очистить, вырезать сердцевину и нарезать мелким кубиком.','Аккуратно вмешать белки в творожную массу, затем яблоки.','Разложить по смазанным маслом формочкам или в одну форму и запекать 35–40 минут.','Остудить прямо в формах и только потом выкладывать: суфле очень нежное.']::text[], 'https://www.iamcook.ru/showrecipe/27633', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
