insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-oladi-morkovnye', 'Морковные оладьи', 'Сладковатые оладьи из тёртой моркови, тесто за пять минут', 'snack', array['snack']::text[], 20, 25, 2, 1, 'egg', array['быстро','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме испечь оладьи в духовке на бумаге: 180°, 15 минут, перевернуть на середине', array['Морковь очистить и натереть на средней тёрке: с крупной она не успеет прожариться.','Яйцо взбить с сахаром в густую пену.','Муку просеять с солью и разрыхлителем и вмешать в яйцо венчиком до теста как нежирная сметана.','Добавить морковь и перемешать ложкой; если тесто вышло густым, влить ложку воды или молока.','Выкладывать ложкой на разогретое масло и жарить на среднем огне до золотистой корочки с двух сторон.']::text[], 'https://1000.menu/cooking/26807-morkovnye-oladi', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
