insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-pirog-luk-yaytso', 'Заливной пирог с зелёным луком и яйцом', 'Пирог на кефире без раскатки: залил тесто, разложил начинку, в духовку', 'snack', array['snack']::text[], 25, 70, 6, 2, 'egg', array['духовка','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Соли — по минимуму; Диме кусочек тёплым', array['Четыре яйца сварить вкрутую, остудить, очистить и мелко нарезать.','Два сырых яйца взбить с солью. Соду размешать в кефире и, когда он вспенится, влить к яйцам.','Понемногу вмешать муку до густого тягучего теста. Духовку разогреть до 180°.','Лук мелко нарезать, смешать с яйцами и растопленным сливочным маслом, посолить.','Форму смазать маслом и присыпать сухарями, налить половину теста, разложить начинку, не доходя до краёв, и залить остальным тестом.','Печь 40–45 минут до сухой шпажки, затем накрыть полотенцем на 10–15 минут и нарезать.']::text[], 'https://www.gastronom.ru/recipe/55550/zalivnoj-pirog-s-zelenym-lukom-i-jajcom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
