insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-pirozhki-kartoshka', 'Пирожки с картошкой в духовке', 'Дрожжевые пирожки с картофельным пюре и жареным луком', 'snack', array['snack']::text[], 50, 180, 12, 3, 'none', array['духовка','выходные','бюджетное','детское','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме отложить часть пюре до перца и сделать пару пирожков без него; дать половинку', array['В тёплой воде растворить сахар и дрожжи и оставить на 10–15 минут до пенки.','Добавить соль и большую часть масла, понемногу вмешать муку и замесить мягкое, чуть липкое тесто. Накрыть и оставить в тепле, пока не вырастет в 1,5–2 раза.','Картофель сварить. Лук мелко нарезать и обжарить на оставшемся масле до золотистого цвета.','Картошку размять в пюре с луком, солью и перцем, остудить и вмешать белок.','Разделить тесто на 12 шариков, раскатать каждый в лепёшку, положить начинку и защипать края.','Выложить швом вниз на противень с бумагой, дать постоять 15 минут и смазать сметаной.','Печь при 200° около 20 минут до золотистого цвета.']::text[], 'https://1000.menu/cooking/2726-pirojki-s-kartoshkoi-iz-drojjevogo-testa-v-duxovke', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
