insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-rulet-lavash-tvorog', 'Рулет из лаваша с творогом и зеленью', 'Холодная закуска без плиты: творог с петрушкой, свёрнутый в лаваш', 'snack', array['snack']::text[], 10, 40, 4, 1, 'cottage', array['будни','без плиты','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Диме без перца', array['Петрушку мелко нарезать и смешать с творогом, сметаной, солью и перцем.','Два листа лаваша положить друг на друга, так рулет не порвётся.','Ровным слоем намазать лаваш начинкой и плотно свернуть рулетом.','Убрать в холодильник на полчаса, чтобы лаваш пропитался, затем нарезать кусочками.']::text[], 'https://www.iamcook.ru/showrecipe/32883', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
