insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-chipsy-yablochnye', 'Яблочные чипсы', 'Хрустящие яблоки из духовки вместо магазинных чипсов', 'snack', array['snack']::text[], 10, 150, 2, 7, 'none', array['духовка','детское','постное','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Малышу давать сидя за столом, по одному ломтику', array['Яблоки вымыть, обсушить и нарезать очень тонкими ломтиками, семечки убрать.','Ломтики ополоснуть холодной водой и снова обсушить полотенцем.','Разложить в один слой на противне с бумагой и посыпать ванильным сахаром и корицей.','Сушить при 50–60° 1,5–2 часа, дверцу духовки держать приоткрытой.','Остудить: чипсы станут хрустящими. Хранить в закрытой банке.']::text[], 'https://1000.menu/cooking/34180-chipsy-iz-yablok', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
