insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-morozhenoe-banan', 'Банановое мороженое', 'Мороженое из двух продуктов и без сахара: бананы и молоко', 'snack', array['snack']::text[], 10, 330, 4, 7, 'dairy', array['без плиты','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Без сахара; Диме небольшую порцию, чуть подтаявшую', array['Спелые бананы очистить, нарезать кружочками и заморозить в контейнере или пакете в один слой, минимум на 3 часа.','Бананы, не размораживая, сложить в блендер и влить молоко.','Взбивать 2–3 минуты до гладкой кремовой массы, давая блендеру передохнуть.','Съесть сразу или убрать в морозилку ещё на 2–3 часа, чтобы мороженое стало плотнее.']::text[], 'https://1000.menu/cooking/24790-domashnee-morojenoe-iz-banana-i-moloka', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
