insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-sendvich-tunec', 'Сэндвичи с тунцом и яйцом', 'Сытный перекус с рыбой за 25 минут, когда до ужина далеко', 'snack', array['snack']::text[], 20, 25, 2, 0, 'fish', array['быстро']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме без майонеза, лука и перца: тунец с яйцом на тосте', array['Яйца сварить вкрутую 8–9 минут, остудить, очистить и нарезать кружочками.','Ломтики хлеба подсушить на сухой сковороде по 30–40 секунд с каждой стороны.','Хлеб смазать майонезом, разложить яйца, слегка посолить и поперчить.','Сверху выложить тунец без масла, кольца лука и листья салата.','Накрыть вторым ломтиком майонезом вниз, разрезать по диагонали и сразу подать.']::text[], 'https://www.iamcook.ru/showrecipe/33772', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
