insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-krupenik', 'Гречневый крупеник с творогом', 'Сладкая запеканка из гречки и творога с румяной корочкой', 'snack', array['breakfast','snack']::text[], 15, 60, 4, 2, 'cottage', array['духовка','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Запеканка из садиковского меню, малышу как есть', array['Гречку сварить и остудить, если нет готовой. Духовку разогреть до 180°.','Яйца слегка взбить с сахаром, ванильным сахаром и щепоткой соли.','Добавить творог и размять; мелкие крупинки не страшны.','Вмешать гречку и выложить массу в смазанную маслом форму.','Сверху разложить кусочки масла и запекать около 40 минут до румяной корочки.','Нарезать и подать тёплым или остывшим со сметаной, вареньем или мёдом.']::text[], 'https://1000.menu/cooking/30194-krupenik-grechnevyi', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
