insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-grushi-zapechennye', 'Груши, запечённые с мёдом и орехами', 'Тёплый фруктовый полдник за 40 минут, без муки и сахара', 'snack', array['snack']::text[], 10, 40, 4, 1, 'none', array['будни','духовка']::text[], array['autumn','winter']::text[], '{}'::text[], 'adapt', 'Диме грушу без кожицы, орехи смолоть в крошку; мёд — если нет аллергии', array['Духовку разогреть до 180°. Восемь половинок орехов отложить, остальные порубить ножом.','Груши разрезать пополам, ложкой вынуть семена и немного мякоти и сбрызнуть лимонным соком.','В каждую половинку положить по две половинки орехов и выложить груши на противень с бумагой.','Полить мёдом, посыпать корицей и рублеными орехами.','Запекать 25–30 минут, пока груши не станут мягкими, но не потеряют форму. Подать тёплыми.']::text[], 'https://1000.menu/cooking/14838-zapechennye-grushi-s-orexami-i-medom', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
