insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-muss-yablochny', 'Яблочный мусс с манкой', 'Пышный мусс из яблок и манки — сладкое без масла и молока', 'snack', array['snack']::text[], 20, 60, 4, 2, 'none', array['детское','бюджетное','постное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Малышу как есть; сахар можно убавить, корицу не класть', array['Яблоки очистить, вырезать сердцевину и нарезать небольшими кусочками.','Сложить в сотейник, добавить сахар, корицу по желанию и воду и томить 7–10 минут до мягкости.','Пробить яблоки блендером в пюре прямо горячими.','Всыпать манку и варить на слабом огне 5–7 минут, помешивая.','Полностью остудить и взбить миксером или блендером до светлой пышной массы.','Разложить по креманкам и сверху положить ягоды или кусочки фруктов.']::text[], 'https://www.iamcook.ru/showrecipe/17170', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
