insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-zapekanka-hlebnaya', 'Хлебная запеканка с яблоками', 'Куда деть чёрствый батон: слоями с яблоком в духовку на 15 минут', 'snack', array['snack']::text[], 15, 30, 2, 1, 'egg', array['быстро','духовка','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Диме яблоко очистить от кожуры, сахара — по минимуму', array['Духовку разогреть до 200°. Хлеб нарезать ломтиками, яблоко — тонкими кружками.','Яйца разболтать с молоком.','Половину ломтиков обмакнуть в смесь и выложить в смазанную маслом форму.','Сверху разложить яблоки и посыпать сахаром с корицей.','Накрыть остальным хлебом, тоже смоченным в смеси, и посыпать сахаром.','Запекать 10–15 минут, немного остудить и подать с джемом или вареньем.']::text[], 'https://www.edimdoma.ru/retsepty/44058-yablochnaya-zapekanka-iz-cherstvogo-hleba', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
