insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-batonchiki-ovsyanye', 'Овсяные батончики с мёдом и сухофруктами', 'Домашние батончики с собой: хлопья, сухофрукты и мёд, сахара нет', 'snack', array['snack']::text[], 15, 90, 8, 7, 'none', array['духовка','детское','постное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Орехи порубить совсем мелко; Диме половинку батончика, мёд — если нет аллергии', array['Духовку разогреть до 160°. Курагу нарезать, орехи порубить.','Смешать в миске хлопья, сухофрукты и орехи.','Мёд прогреть до жидкого и размешать с маслом, залить хлопья и перемешать, чтобы влажными стали все хлопья.','Выложить в небольшую форму с бумагой и плотно утрамбовать.','Печь около 30 минут до золотистого цвета.','Полностью остудить в форме и только потом нарезать на батончики.']::text[], 'https://eda.rambler.ru/recepty/zavtraki/ovsjanie-batonchiki-s-medom-suhofruktami-i-orehami-37466', 'eda.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
