insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-shariki-kartofelnye', 'Картофельные шарики с сыром', 'Шарики из пюре с тянущимся сыром внутри, запечённые без фритюра', 'snack', array['snack']::text[], 35, 75, 4, 2, 'dairy', array['духовка','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме отложить часть пюре до перца; дать тёплыми, не горячими — сыр внутри горячий', array['Картофель сварить в кожуре в подсоленной воде, очистить и растолочь в пюре.','В тёплое пюре вбить одно яйцо, поперчить, всыпать муку и замесить густое липкое тесто.','Сыр нарезать небольшими кубиками. Духовку разогреть до 180°.','Мокрыми руками сделать из теста лепёшку, положить в центр кубик сыра и защипнуть в шарик.','Второе яйцо взболтать со щепоткой соли, обмакнуть шарики и обвалять в сухарях.','Выложить в форму и запекать 15–18 минут до румяной корочки.']::text[], 'https://www.iamcook.ru/showrecipe/37920', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
