insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-pechenye-banan', 'Овсяное печенье с бананом без муки', 'Печенье из хлопьев и банана: ложка сахара на всё, без муки и яиц', 'snack', array['snack']::text[], 15, 45, 4, 5, 'none', array['духовка','детское','постное','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Сахара почти нет; Диме 1–2 печенья, изюм порезать', array['Изюм запарить кипятком. Духовку разогреть до 170°.','Банан размять вилкой в пюре, добавить сахар и масло.','Отдельно смешать хлопья, кунжут и щепотку соли и частями вмешать в банан; если масса суховата, добавить ложку воды.','Добавить отжатый изюм и разрыхлитель и перемешать руками.','Мокрыми руками скатать шарики с грецкий орех, выложить на бумагу и приплюснуть потоньше.','Печь 20–30 минут до золотистого цвета и остудить на противне.']::text[], 'https://1000.menu/cooking/31830-ovsyanoe-pechene-s-bananom', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
