insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-konfety-suhofrukty', 'Конфеты из сухофруктов и орехов', 'Конфеты без сахара: сухофрукты, орехи и капля мёда', 'snack', array['snack']::text[], 25, 150, 10, 7, 'none', array['без плиты','постное','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое, хоть и без сахара: Диме 1–2 конфеты без какао; мёд — если нет аллергии', array['Сухофрукты промыть, залить кипятком на 15 минут, слить воду и обсушить.','Орехи промыть и подсушить, жарить не нужно.','Измельчить сухофрукты с орехами блендером или мясорубкой в однородную массу, при необходимости влить ложку холодной воды.','Вмешать мёд до густой липкой массы.','Мокрыми руками скатать шарики размером с чайную ложку и обвалять в кунжуте или какао.','Убрать в холодильник на 2 часа, чтобы конфеты затвердели.']::text[], 'https://1000.menu/cooking/15031-konfety-iz-suxofruktov-kuragi-i-chernosliva-i-orexov', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
