insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-pirog-tyortyy', 'Тёртый пирог с вареньем', 'Песочный пирог из детства: варенье под тёртой крошкой из теста', 'dessert', array['snack']::text[], 25, 80, 10, 4, 'egg', array['духовка','выходные','детское','бюджетное','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме небольшой кусок, не чаще 2–3 раз в неделю вместе с другими сладостями', array['Масло заранее достать, чтобы стало мягким. Духовку разогреть до 180°.','Масло растереть с сахаром и яйцами до однородности.','Всыпать муку с разрыхлителем и быстро замесить мягкое тесто, долго не мять.','Треть теста завернуть в пакет и убрать в морозилку.','Остальное тесто раскатать по дну формы около 24×34 см, застеленной бумагой, и намазать вареньем.','Замёрзший кусок натереть на крупной тёрке поверх варенья.','Печь около 35 минут до золотистого цвета и резать, когда пирог полностью остынет.']::text[], 'https://menunedeli.ru/recipe/tyortyj-pirog-s-varenem/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
