insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-rulet-biskvitny', 'Бисквитный рулет с вареньем', 'Быстрый рулет: бисквит из четырёх яиц и любое густое варенье', 'dessert', array['snack']::text[], 20, 45, 6, 2, 'egg', array['будни','духовка','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме один кусочек, не чаще 2–3 раз в неделю вместе с другими сладостями', array['Духовку разогреть до 180°. Муку просеять с разрыхлителем.','Отделить белки от желтков. Желтки взбить с сахаром до увеличения объёма и, не выключая миксер, всыпать муку.','Белки взбить в чистой миске до устойчивых пиков и осторожно вмешать в желтковую массу.','Вылить тесто на противень с бумагой и разровнять лопаткой.','Печь 15–20 минут до румянца и сухой шпажки, затем перевернуть на чистое полотенце и снять бумагу.','Сразу намазать вареньем, отступив от краёв 2 см, и плотно свернуть с помощью полотенца. Резать остывшим.']::text[], 'https://1000.menu/cooking/31270-biskvitnyi-rulet-s-varenem-v-duxovke', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
