insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-pirozhnoe-kartoshka', 'Пирожное «Картошка»', 'Пирожное без выпечки из печенья, сгущёнки и какао', 'dessert', array['snack']::text[], 30, 150, 12, 4, 'none', array['без плиты','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое, с какао: Диме одно пирожное без орехов, не чаще раза в неделю, в счёт сладкого', array['Масло заранее достать, чтобы стало мягким.','Печенье измельчить в мелкую крошку блендером или скалкой в пакете, орехи тоже измельчить.','Смешать крошку, орехи и какао, отложив ложку какао для обсыпки.','Отдельно взбить масло со сгущёнкой и соединить с сухой смесью до однородности.','Слепить пирожные-картошки и убрать в холодильник на 2 часа, чтобы масло застыло.','Обвалять каждое пирожное в оставшемся какао.']::text[], 'https://1000.menu/cooking/34638-pirojnoe-kartoshka-iz-pechenya-so-sgushchenkoi', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
