insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-krambl-yablochny', 'Яблочный крамбл', 'Яблоки под хрустящей песочной крошкой, подаётся тёплым', 'dessert', array['snack']::text[], 20, 45, 3, 1, 'none', array['будни','духовка','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме небольшую порцию без орехов, не чаще 2–3 раз в неделю вместе с другими сладостями', array['Масло нарезать кубиками и убрать в морозилку. Орехи порубить и подсушить на сухой сковороде 5 минут.','Яблоки очистить от кожуры и сердцевины и нарезать небольшими кусочками.','На сковороде растопить коричневый сахар с корицей, положить яблоки и прогреть, пока они не покроются карамелью и не дадут сок.','Муку с сахаром перетереть с холодным маслом вилкой в мелкую крошку.','Выложить яблоки в форму, посыпать орехами, сверху — крошкой.','Запекать при 180° 25 минут и подать тёплым.']::text[], 'https://1000.menu/cooking/11422-yablochnyi-krambl-s-yablokami', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
