insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-pirog-vishnya', 'Пирог с вишней на кефире', 'Простой пирог на кефире с кислой вишней сверху', 'dessert', array['snack']::text[], 15, 60, 8, 2, 'egg', array['духовка','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме небольшой кусок, не чаще 2–3 раз в неделю вместе с другими сладостями', array['Вишню разморозить и откинуть на сито, чтобы стёк сок. Духовку разогреть до 180°.','Яйца взбить с сахаром в пышную светлую массу и на малых оборотах вмешать кефир.','Муку просеять с разрыхлителем в яичную массу и перемешать венчиком; если тесто жидкое, добавить ещё ложку-две муки.','Форму около 20 см смазать маслом, вылить тесто и разложить сверху вишню.','Печь 35–45 минут до сухой шпажки, остудить и посыпать сахарной пудрой.']::text[], 'https://1000.menu/cooking/27788-pirog-na-kefire-s-vishnyami', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
