insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-maffiny-tykva', 'Тыквенные маффины', 'Яркие маффины на тыквенном пюре — осенняя выпечка к чаю', 'dessert', array['snack']::text[], 25, 65, 12, 3, 'egg', array['духовка','выходные','детское','на 2–3 дня']::text[], array['autumn','winter']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме один маффин без орехов, не чаще 2–3 раз в неделю вместе с другими сладостями', array['Тыкву натереть на крупной тёрке, прогреть в микроволновке 5–10 минут до мягкости, размять в пюре и остудить.','Духовку разогреть до 180°. Муку просеять с разрыхлителем, корицей и щепоткой соли.','Яйца взбить с сахаром, влить масло и вмешать тыквенное пюре.','Всыпать сухую смесь и перемешать венчиком только до исчезновения комочков.','По желанию добавить поджаренные рубленые орехи.','Разложить по формочкам чуть больше чем наполовину и печь 25–35 минут до сухой зубочистки.']::text[], 'https://1000.menu/cooking/16982-tykvennye-maffiny-s-tykvoi', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
