insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-bulochki-tvorozhnye', 'Творожные булочки без дрожжей', 'Мягкие булочки на твороге: без дрожжей и ожидания, 40 минут', 'dessert', array['snack']::text[], 20, 40, 8, 4, 'cottage', array['будни','духовка','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме одну булочку, не чаще 2–3 раз в неделю вместе с другими сладостями', array['Духовку разогреть до 180°. Творог, яйца, соль, сахар и ванильный сахар пробить блендером до гладкости.','Муку просеять с разрыхлителем и вмешать: тесто выйдет густым и липким, но держит форму.','Влажными руками скатать небольшие булочки и выложить на противень с бумагой с промежутками.','Печь около 15 минут до румянца.','Достать, смазать молоком, посыпать сахаром и допечь ещё 5 минут.']::text[], 'https://1000.menu/cooking/28089-tvorojnye-bulochki-v-duxovke-bez-drojjei', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
