insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-ponchiki-tvorozhnye', 'Творожные пончики', 'Шарики из творожного теста, жаренные до золотистой корочки', 'dessert', array['snack']::text[], 40, 50, 5, 1, 'cottage', array['выходные','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое и во фритюре: Диме один пончик не чаще раза в неделю, в счёт сладкого', array['Яйца взбить с сахаром до пышной светлой массы.','Добавить творог, щепотку соли, ванильный сахар и соду и перемешать.','Понемногу подсыпать муку и замесить мягкое тесто, которое скатывается в шарики.','В небольшой глубокой сковороде или сотейнике разогреть масло.','Скатать шарики размером с грецкий орех и жарить порциями на небольшом огне 3–4 минуты, переворачивая: в масле они вырастут.','Выложить на бумажное полотенце, чтобы ушёл лишний жир.']::text[], 'https://1000.menu/cooking/21202-tvorojnye-ponchiki-v-masle', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
