insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-sloyki-yabloko', 'Слойки с яблоками', 'Хрустящие слойки с яблоком и корицей из готового теста', 'dessert', array['snack']::text[], 20, 50, 6, 2, 'none', array['духовка','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме половинку слойки, не чаще 2–3 раз в неделю вместе с другими сладостями', array['Тесто разморозить в холодильнике. Духовку разогреть до 180°.','Яблоки очистить, нарезать мелким кубиком и перемешать с сахаром и корицей.','Тесто раскатать в одном направлении в пласт толщиной 4 мм и нарезать прямоугольниками; на одной половине каждого сделать надрезы.','На целую половину выложить по две ложки начинки, края смазать яйцом, накрыть надрезанной частью и прижать вилкой.','Переложить на противень с бумагой, смазать яйцом и печь 25–30 минут до золотистого цвета.','Посыпать сахарной пудрой и подать тёплыми или остывшими.']::text[], 'https://menunedeli.ru/recipe/slojki-s-yablokami-iz-gotovogo-sloyonogo-testa/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
