insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-zhele-smetannoe', 'Сметанное желе с бананом', 'Нежный молочный десерт на сметане с кусочками банана', 'dessert', array['snack']::text[], 15, 120, 4, 2, 'dairy', array['без плиты','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме небольшую порцию, не чаще 2–3 раз в неделю вместе с другими сладостями', array['Желатин залить холодной кипячёной водой и оставить набухать на 10–15 минут.','Сметану размешать с сахаром и оставить на 10 минут, чтобы сахар растворился.','Желатин растворить в микроволновке или на водяной бане, не доводя до кипения.','Через ситечко влить желатин в сметану и перемешать.','Добавить банан мелким кубиком, разлить по стаканчикам и убрать в холодильник на 1,5–2 часа.']::text[], 'https://www.iamcook.ru/showrecipe/25675', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
