insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-plyushki', 'Плюшки с сахаром', 'Сдобные плюшки-сердечки с сахарной корочкой, как в булочной', 'dessert', array['snack']::text[], 40, 150, 14, 3, 'none', array['духовка','выходные','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме половинку плюшки, не чаще 2–3 раз в неделю вместе с другими сладостями', array['Дрожжи залить тёплым молоком с ложкой сахара и оставить в тепле на 15–20 минут.','Яйцо размешать с остальным сахаром для теста и солью, влить растительное масло и опару.','Всыпать просеянную муку и замесить мягкое тесто, которое не липнет к рукам. Оставить в тепле на 1–1,5 часа.','Разделить тесто на шарики с мандарин, каждый раскатать, смазать растопленным сливочным маслом и посыпать сахаром.','Свернуть рулетом, надрезать вдоль, не доходя 1 см до края, и раскрыть сердечком.','Выложить на смазанный противень и печь при 180° 15–20 минут.','Горячие плюшки смазать сиропом из воды и сахара, чтобы блестели.']::text[], 'https://1000.menu/cooking/11857-plushki-moskovskie', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
