insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-keks-limonny', 'Лимонный кекс на кефире', 'Кекс с цедрой и лимонной глазурью, хватает к чаю на два-три дня', 'dessert', array['snack']::text[], 20, 75, 8, 4, 'egg', array['духовка','выходные','детское','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме небольшой кусок, не чаще 2–3 раз в неделю вместе с другими сладостями', array['Духовку разогреть до 180°. Растопленное масло взбить миксером с сахаром.','Добавить яйца, цедру всего лимона и 2 ст. л. сока и перемешать до однородности.','Муку смешать с крахмалом, содой, разрыхлителем и щепоткой соли и просеять в жидкую основу.','Влить тёплый кефир и перемешать до однородного теста.','Выложить в смазанную и присыпанную мукой форму и печь 40–50 минут до сухой шпажки.','Сахарную пудру растереть с оставшимся лимонным соком и полить кекс.']::text[], 'https://1000.menu/cooking/46682-limonnyi-keks-na-kefire-s-razryxlitelem', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
