insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-morozhenoe-yogurt', 'Йогуртовое мороженое с ягодами', 'Мороженое на палочке из йогурта и ягод, сладость только от мёда', 'dessert', array['snack']::text[], 10, 240, 5, 7, 'dairy', array['без плиты','детское']::text[], array['summer']::text[], '{}'::text[], 'adapt', 'Сладкое, с мёдом: Диме половинку порции, чуть подтаявшую; мёд — если нет аллергии', array['Стаканчики для мороженого застелить плёнкой, так его легко будет вынуть.','Чернику пробить блендером, оставив кусочки, добавить мёд и йогурт и слегка перемешать разводами.','Разложить по стаканчикам, вставить палочки и добавить по несколько целых ягод голубики.','Убрать в морозилку на 3–4 часа или на ночь.','Перед подачей на секунду опустить стаканчик в горячую воду и вынуть мороженое.']::text[], 'https://www.gastronom.ru/recipe/55179/jogurtovoe-morozhenoe-s-jagodami', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
