insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-paskha', 'Творожная пасха', 'Пасха из творога с изюмом и орехами, сахара всего ложка', 'dessert', array['snack']::text[], 30, 720, 6, 5, 'cottage', array['праздничное','без плиты']::text[], array['spring']::text[], '{}'::text[], 'adapt', 'Диме кусочек без орехов, изюм порезать; в счёт сладкого', array['Творог дважды пропустить через мясорубку или протереть через сито, блендер не подходит.','Изюм запарить кипятком, слить воду и промыть, орехи измельчить.','Смешать творог с мягким маслом, сметаной, сахаром, ванильным сахаром, изюмом и орехами. Масса должна получиться плотной.','Пасочницу или дуршлаг застелить влажной марлей в два слоя, плотно уложить массу и накрыть краями марли.','Поставить сверху груз и убрать в холодильник на ночь, подставив миску для стекающей сыворотки.','Перевернуть пасху на блюдо, снять марлю и украсить орехами или сухофруктами.']::text[], 'https://1000.menu/cooking/41674-pasxa-prostaya-tvorojnaya', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
