insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('dr-kompot-yabloki', 'Компот из свежих яблок', 'Компот из трёх яблок за 15 минут, сахар — по вкусу', 'drink', array['snack']::text[], 10, 45, 6, 2, 'none', array['будни','бюджетное','постное','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Диме — тёплый или комнатной температуры', array['Воду довести до кипения. Яблоки вымыть и нарезать дольками без сердцевины.','Опустить яблоки в кипяток, убавить огонь до минимума и всыпать сахар.','Варить 5 минут, чтобы дольки не разварились.','Снять с огня, накрыть крышкой и дать настояться хотя бы полчаса: чем дольше, тем ярче вкус.']::text[], 'https://www.iamcook.ru/showrecipe/16155', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
