insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('dr-kisel-molochny', 'Кисель молочный', 'Садиковский кисель на молоке за 15 минут — к запеканке или печенью', 'drink', array['snack']::text[], 10, 15, 3, 1, 'dairy', array['быстро','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Из садиковского меню; Диме — тёплый', array['Крахмал размешать в холодной воде и процедить.','Молоко довести до кипения, всыпать сахар и ванильный сахар.','Тонкой струйкой, помешивая, влить крахмал: кисель сразу загустеет.','Проварить на самом слабом огне 2 минуты, не переставая мешать.','Остудить до комнатной температуры и подать с печеньем, оладьями или запеканкой.']::text[], 'https://menunedeli.ru/recipe/molochnyj-kisel-kak-v-detskom-sadu/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
