insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('dr-limonad', 'Домашний лимонад с мёдом', 'Летний лимонад на мёде за пять минут, без газировки', 'drink', array['snack']::text[], 5, 5, 4, 1, 'none', array['быстро','без плиты','постное']::text[], array['summer']::text[], '{}'::text[], 'adapt', 'Кислое и с мёдом: Диме разбавить водой пополам; мёд — если нет аллергии', array['Из лимонов выжать сок, от одного оставить несколько кружочков.','Сок развести водой и добавить мёд.','Перемешать, пока мёд не растворится.','Положить кружочки лимона и лёд и сразу подать.']::text[], 'https://1000.menu/cooking/8386-domashnij-limonad', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
