insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('dr-kokteyl-klubnichny', 'Клубничный молочный коктейль', 'Розовый коктейль из клубники и холодного молока, без мороженого', 'drink', array['breakfast','snack']::text[], 10, 10, 4, 0, 'dairy', array['быстро','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Диме полстакана, без льда', array['Клубнику промыть и убрать хвостики, замороженную чуть разморозить.','Пробить клубнику блендером и протереть через сито, чтобы убрать косточки.','Добавить сахар, ванильный сахар и хорошо охлаждённое молоко.','Взбивать на высокой скорости до густой пены и сразу разлить по стаканам.']::text[], 'https://menunedeli.ru/recipe/klubnichnyj-koktejl-bez-morozhenogo/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
