insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-grechnevyi-s-kuritsei', 'Гречневый суп с курицей', 'Простой суп на бульоне из бёдер с гречкой и картошкой', 'soup', array['lunch']::text[], 25, 60, 12, 3, 'poultry', array['на 2–3 дня','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить ему порцию до соли, курицу нарезать мелко. Лук и морковь можно не обжаривать, а положить в бульон сырыми — тогда суп подойдёт ему целиком.', array['Бёдра залить 4 л холодной воды, довести до кипения и снять пену. Варить на слабом огне 30–40 минут.','Курицу вынуть, мясо снять с костей и нарезать. Гречку промыть.','Лук мелко нарезать, морковь натереть и обжарить на масле 5–7 минут до мягкости.','В бульон положить картофель брусочками и варить 10–15 минут.','Добавить гречку и зажарку и варить ещё 5–10 минут, пока крупа и картофель не станут мягкими.','Вернуть курицу, посолить, всыпать зелень и дать постоять под крышкой 10 минут.']::text[], 'https://www.gastronom.ru/recipe/59091/grechnevyj-sup-s-kuricej-i-kartoshkoj', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
