insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-kulesh', 'Кулеш', 'Густая казачья похлёбка из пшена и картошки с поджаренной грудинкой', 'soup', array['lunch']::text[], 20, 45, 12, 3, 'red-meat', array['на 2–3 дня','бюджетное','будни']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить ему пшено с картофелем и бульоном до жареной грудинки и соли.', array['Пшено промыть до прозрачной воды. Всыпать в 4 л кипящей воды и варить 10 минут.','Картофель нарезать кубиками, добавить к пшену и варить около 15 минут, почти до готовности.','Грудинку и лук мелко нарезать и обжарить на сковороде до золотистого цвета.','Переложить в кастрюлю, посолить и варить ещё 5–7 минут.','Посыпать рубленой петрушкой. Кулеш густеет, при разогреве подлить воды.']::text[], 'https://www.gastronom.ru/recipe/23959/kazackij-kulesh', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
