insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-kabachki-pyure', 'Суп-пюре из кабачков', 'Кабачки с картошкой и сливками, к супу — хрустящие сухарики', 'soup', array['lunch']::text[], 30, 55, 12, 3, 'none', array['на 2–3 дня']::text[], array['summer','autumn']::text[], '{}'::text[], 'adapt', 'Отложить ему порцию пюре со сливками до соли и перца. Сухарики — без паприки.', array['Лук, морковь и чеснок нарезать и обжарить на масле в кастрюле 3–4 минуты.','Добавить кабачки кубиками и готовить 5 минут, затем картофель кубиками — ещё 5 минут, помешивая.','Залить 1,6 л горячей воды или бульона, накрыть и варить 20–25 минут до мягкости.','Для сухариков хлеб нарезать кубиками, перемешать с ложкой масла и паприкой и подсушить в духовке при 180° 10–12 минут.','Суп немного остудить и пробить блендером до гладкости.','Влить тёплые сливки, посолить, поперчить и прогреть, не доводя до кипения. Сухарики класть в тарелки.']::text[], 'https://menunedeli.ru/recipe/sup-pyure-iz-kabachkov-i-kartofelya/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
