insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-goroshek-pyure', 'Суп-пюре из зелёного горошка', 'Яркий суп из замороженного горошка с картошкой, сливками и мятой', 'soup', array['lunch']::text[], 20, 35, 12, 3, 'none', array['на 2–3 дня','будни']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить ему порцию до соли.', array['Картофель нарезать кусочками, опустить в 2 л кипящего бульона или воды и варить 10 минут.','Лук и сельдерей мелко нарезать, обжарить на половине масла 3 минуты и переложить в кастрюлю.','Горошек обжарить на оставшемся масле 3 минуты. Половину положить в суп и варить 5 минут.','Добавить листья мяты и пробить суп блендером до гладкости.','Влить сливки, положить оставшийся горошек, посолить и прогреть, не доводя до кипения.']::text[], 'https://www.gastronom.ru/recipe/4714/sup-pyure-iz-zelenogo-goroshka', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
