insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-kartofelnyi-pyure', 'Картофельный суп-пюре', 'Бархатный суп из картошки со сливками — сытно и недорого', 'soup', array['lunch']::text[], 15, 45, 12, 3, 'none', array['на 2–3 дня','бюджетное','будни','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить ему порцию со сливками до соли и перца и пробить отдельно. Кинзу ему не класть.', array['Лук нарезать кубиками, морковь натереть и потушить на масле в кастрюле до мягкости.','Добавить картофель крупными кубиками, залить 2,5 л бульона или воды и варить около 20 минут до мягкости.','Убавить огонь, влить сливки, посолить, поперчить и томить ещё 10 минут.','Пробить суп блендером до однородности. Если густо, подлить горячего бульона.','Разлить по тарелкам и посыпать рубленым укропом и кинзой.']::text[], 'https://www.gastronom.ru/recipe/59094/kartofelnyj-sup-pyure', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
