insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-morkovnyi-pyure', 'Морковный суп-пюре', 'Нежный суп из моркови на овощном бульоне с хрустящими гренками', 'soup', array['lunch']::text[], 20, 60, 10, 3, 'none', array['на 2–3 дня','постное','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить ему порцию до соли, гренки — без чеснока.', array['Лук мелко нарезать и обжарить на масле в кастрюле до прозрачности.','Добавить морковь кубиками, паприку и куркуму и готовить 3 минуты, помешивая.','Залить 2 л овощного бульона или воды, накрыть и варить на тихом огне около 45 минут, пока морковь не разварится. Если жидкость сильно выкипит, подлить.','Для гренок хлеб нарезать кубиками и обжарить на масле с раздавленным чесноком до румяности.','Суп пробить блендером до кремовой консистенции и посолить. Подавать с гренками и зеленью.']::text[], 'https://menunedeli.ru/recipe/morkovnyj-sup-pyure/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
