insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-tomatnyi-pyure', 'Томатный суп-пюре', 'Суп из свежих и консервированных помидоров с базиликом', 'soup', array['lunch']::text[], 20, 40, 10, 3, 'none', array['на 2–3 дня','постное','будни']::text[], array['summer','autumn']::text[], '{}'::text[], 'adapt', 'Отложить ему порцию до соли и перца. Суп кисловат — можно добавить ему ложку сметаны.', array['Морковь и сельдерей нарезать крупно, лук и чеснок — мелко. Обжарить на масле в кастрюле 10–15 минут до мягкости.','Свежие помидоры нарезать крупными кусками.','Влить 1,6 л овощного бульона или воды, добавить свежие и консервированные томаты и довести до кипения. Варить 10 минут на слабом огне.','Снять с огня, посолить, поперчить, положить базилик и пробить блендером.','Перед подачей прогреть. Рис, гренки или сливки добавлять прямо в тарелку.']::text[], 'https://menunedeli.ru/recipe/tomatnyj-sup-pyure/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
