insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-minestrone', 'Минестроне', 'Итальянский овощной суп с фасолью, тыквой и мелкими макаронами', 'soup', array['lunch']::text[], 30, 60, 10, 3, 'legume', array['на 2–3 дня','постное']::text[], array['summer','autumn']::text[], '{}'::text[], 'adapt', 'Отложить ему порцию до соли и перца, фасоль размять вилкой. Бобовые — не чаще 2–3 раз в неделю.', array['Одну морковку отложить, остальную морковь, лук, сельдерей и чеснок нарезать очень мелко. Картофель, тыкву, кабачки и отложенную морковь нарезать кубиками.','Мелко нарезанные овощи потушить на оливковом масле в кастрюле 10 минут до мягкости.','Добавить картофель, тыкву и томаты и залить водой на 4 см выше овощей, около 2,5 л. Довести до кипения, немного посолить и варить 15 минут.','Положить кабачки, шпинат и фасоль без жидкости и варить 10 минут.','Всыпать макароны и варить ещё 5 минут. Посолить и поперчить.','Подавать с тёртым сыром и каплей оливкового масла. Макароны набухают, при разогреве подлить воды.']::text[], 'https://www.gastronom.ru/recipe/23399/minestrone-s-fasolyu', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
