insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-finskii-s-gorbushei', 'Финский суп с горбушей и сливками', 'Красная рыба и картошка в сливочном бульоне с укропом', 'soup', array['lunch']::text[], 15, 40, 10, 2, 'fish', array['на 2–3 дня','будни']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить ему порцию до досаливания и перца, рыбу проверить на косточки.', array['Лук нарезать и обжарить на растительном масле в кастрюле до золотистого цвета.','Влить 1,9 л воды, положить лавровый лист, немного посолить и довести до кипения.','Добавить картофель кубиками не крупнее 1,5 см и варить 15 минут.','Рыбу нарезать небольшими кубиками, опустить в суп и после закипания варить 5 минут.','Влить сливки и довести до кипения. Муку размешать в 100 мл холодной воды, влить через сито и, помешивая, снова довести до кипения.','Посолить, поперчить, положить сливочное масло и снять с огня. Подавать с рубленым укропом.']::text[], 'https://www.gastronom.ru/recipe/32611/finskij-sup-s-lososem-i-slivkami-lohikejtto', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
