insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-rybnye-frikadelki', 'Суп с рыбными фрикадельками', 'Картофельный суп с нежными фрикадельками из хека, как в детском саду', 'soup', array['lunch']::text[], 35, 50, 10, 3, 'fish', array['на 2–3 дня','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Рецепт детсадовский: соли мало, взрослым досолить в тарелке.', array['Рыбное филе прокрутить через мясорубку. Лук для фарша мелко нарезать и проварить в кипятке 2–3 минуты, чтобы ушла горечь.','Смешать фарш с белками и луком, слегка посолить и вымесить. Слепить фрикадельки размером с грецкий орех.','Картофель, морковь и лук для супа нарезать мелкими кубиками.','Картофель опустить в 3 л кипящей слегка подсоленной воды и варить 5 минут.','Лук с морковью потушить на сливочном масле 3–4 минуты, без румяной корочки, и переложить в кастрюлю.','Довести до кипения, опустить фрикадельки, накрыть и варить на слабом огне 10 минут.']::text[], 'https://menunedeli.ru/recipe/kartofelnyj-sup-s-rybnymi-frikadelkami-kak-v-detskom-sadu/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
