insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-nut-s-govyadinoi', 'Суп с нутом и говядиной', 'Сытный суп с нутом, говядиной, сладким перцем и томатом', 'soup', array['lunch']::text[], 25, 100, 10, 3, 'red-meat', array['на 2–3 дня','выходные']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить ему порцию с нутом, картофелем и мясом до зажарки и соли, нут размять. Бобовые — не чаще 2–3 раз в неделю.', array['Нут с вечера замочить в холодной воде, утром промыть.','Нут и говядину залить 3 л воды, довести до кипения, снять пену и варить на слабом огне около часа, пока нут не станет мягким.','Мясо вынуть и нарезать кусочками. В бульон положить картофель кубиками.','Лук обжарить на масле, добавить морковь и болгарский перец и готовить 5 минут. Положить томатную пасту, подлить немного бульона и потушить 2–3 минуты.','Когда картофель почти сварится, переложить зажарку и мясо в кастрюлю и варить 10 минут.','Посолить, поперчить, всыпать зелень и снять с огня.']::text[], 'https://www.iamcook.ru/showrecipe/21499', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
