insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-shurpa', 'Шурпа из баранины', 'Наваристый бульон на баранине с крупной картошкой, помидорами и перцем', 'soup', array['lunch']::text[], 30, 180, 10, 3, 'red-meat', array['на 2–3 дня','выходные']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить ему порцию с картофелем и морковью до чили, специй и соли, мясо снять с кости и нарезать мелко.', array['Баранину нарезать большими кусками, залить 3 л воды и довести до кипения, снимая пену.','Положить луковицу, надрезанную крестом, и крупный помидор целиком. Варить под крышкой на очень слабом огне 1,5–2 часа, пока мясо не станет мягким.','Мясо вынуть. Лук и помидор протереть через сито и вернуть в бульон, бульон процедить.','В кипящий бульон положить целые картофелины и морковь крупными кружками. Через 10 минут добавить мелкие помидоры целиком и болгарский перец четвертинками.','Томить без крышки на слабом огне 20 минут. Отлить порцию Диме, затем положить стручок чили, зиру, соль и перец и томить ещё 10–20 минут до мягкости овощей.','Вернуть мясо, добавить нарезанный чеснок и пучок кинзы. После закипания снять с огня, через 5 минут кинзу вынуть.','В тарелку класть кусок мяса и овощи, посыпать свежей кинзой.']::text[], 'https://menunedeli.ru/recipe/shurpa-iz-baraniny-recept-klassicheskij/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
