insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-perlovyi-s-rebrami', 'Перловый суп со свиными рёбрышками', 'Наваристый суп с перловкой, картошкой и мясом с рёбрышек', 'soup', array['lunch']::text[], 20, 100, 10, 3, 'red-meat', array['на 2–3 дня','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить ему порцию до соли и перца, мясо нарезать мелко. Перловка должна хорошо развариться.', array['Перловку замочить на 10–12 часов, удобно с вечера.','Рёбра залить водой, довести до кипения, проварить 5 минут и слить воду. Залить 3,5 л чистой воды и варить бульон 40–60 минут, снимая пену.','Рёбра вынуть. В бульон всыпать промытую перловку и варить 10–15 минут до полуготовности.','Добавить картофель кубиками, нарезанные лук и морковь и варить ещё 10–15 минут.','Мясо снять с костей и вернуть в суп. Положить лавровый лист и орегано, посолить, поперчить и проварить 5 минут.','Дать настояться под крышкой 10–15 минут и подавать с укропом.']::text[], 'https://www.iamcook.ru/showrecipe/19469', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
