insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-sup-gulyash', 'Суп-гуляш', 'Венгерский густой суп с говядиной, паприкой, картошкой и перцем', 'soup', array['lunch']::text[], 30, 120, 10, 3, 'red-meat', array['на 2–3 дня','выходные']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить ему порцию до соли и перца, мясо нарезать мелко. Сладкая паприка ему можно.', array['Говядину нарезать кубиками 2–3 см, лук — кубиком, чеснок — мелко. Перец и помидоры нарезать кубиками, картофель — крупно.','В кастрюле с толстым дном обжарить мясо на масле до корочки. Убавить огонь, всыпать паприку и чеснок и перемешать.','Влить воду почти вровень с мясом и тушить под крышкой 1–1,5 часа, подливая воду при необходимости.','Добавить лук, картофель, перец, помидоры и томатную пасту и прогреть 5 минут.','Влить горячую воду, чтобы она почти покрыла мясо и овощи, около 2 л, и варить под крышкой на слабом огне 15–20 минут.','Посолить, поперчить и дать настояться под крышкой 15 минут.']::text[], 'https://1000.menu/cooking/30824-sup-gulyash-po-vengerski', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
