insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-tarator', 'Таратор', 'Болгарский холодный суп из йогурта с огурцом, укропом и орехами', 'soup', array['lunch']::text[], 20, 80, 10, 2, 'dairy', array['на 2–3 дня','без плиты']::text[], array['summer']::text[], '{}'::text[], 'adapt', 'Отложить ему основу до чеснока, соли и перца, орехи смолоть в пыль.', array['Йогурт и минеральную воду заранее охладить.','Чеснок растереть с солью. Огурцы очистить и натереть на крупной тёрке или нарезать тонкой соломкой.','Орехи растолочь в крошку, укроп мелко порубить.','Смешать огурцы с соком, чеснок, орехи и укроп, влить йогурт и оливковое масло, поперчить. Убрать в холодильник на час.','Основу хранить без воды. Перед подачей развести холодной минеральной водой до густоты жидкой сметаны.']::text[], 'https://www.gastronom.ru/recipe/31294/tarator-holodnyy-bolgarskiy-sup-s-ogurcom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
