insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-kukuruznaya-krupa-s-kuritsei', 'Суп с кукурузной крупой и курицей', 'Золотистый куриный суп с кукурузной крупой, картошкой и горошком', 'soup', array['lunch']::text[], 20, 90, 10, 3, 'poultry', array['на 2–3 дня','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить ему порцию до соли и перца, курицу нарезать мелко.', array['Курицу залить 3,5 л воды, положить целую луковицу и стебель сельдерея, довести до кипения и варить 35 минут, снимая пену.','Лук и сельдерей выбросить, курицу вынуть и разобрать мясо. Бульон процедить.','Кукурузную крупу промыть до прозрачной воды, иначе суп будет горчить.','В кипящий бульон положить тёртую морковь и крупу и варить 15 минут, помешивая.','Добавить картофель кубиками и горошек и варить ещё 20 минут.','Вернуть мясо, положить лавровый лист, посолить, поперчить и проварить 5 минут. Дать настояться 10 минут.']::text[], 'https://1000.menu/cooking/44230-sup-s-kukuruznoi-krupoi-i-kuricei', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
