insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-bulgur-s-kuritsei', 'Суп с булгуром и курицей', 'Быстрый куриный суп с булгуром, помидором и сладким перцем', 'soup', array['lunch']::text[], 20, 45, 12, 3, 'poultry', array['на 2–3 дня','будни']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить ему порцию до зажарки и соли, курицу нарезать мелко.', array['Курицу нарезать кусочками, залить 4 л воды, довести до кипения и снять пену.','Булгур промыть и вместе с картофелем кубиками положить в кастрюлю. Варить 15 минут.','Лук, морковь, перец и помидор нарезать и обжарить на масле 2–3 минуты.','Переложить зажарку в суп, посолить, поперчить и варить ещё 10 минут.','Всыпать зелень, снять с огня и дать постоять под крышкой 5–10 минут.']::text[], 'https://1000.menu/cooking/53145-sup-s-bulgurom-i-kuricei', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
