insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-tsvetnaya-kapusta-s-kuritsei', 'Куриный суп с цветной капустой', 'Лёгкий суп на курице с цветной капустой, картошкой и горошком', 'soup', array['lunch']::text[], 20, 50, 10, 3, 'poultry', array['на 2–3 дня','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить ему порцию с капустой, картофелем и курицей до зажарки и соли.', array['Курицу залить 3,5 л воды, довести до кипения, снять пену и варить на умеренном огне 20 минут.','Положить картофель небольшими кусочками и варить 10 минут.','Цветную капусту разобрать на мелкие соцветия, добавить в суп и варить 5–7 минут.','Лук мелко нарезать, морковь натереть и обжарить на масле до мягкости.','Переложить зажарку в кастрюлю, добавить горошек, посолить, поперчить и варить ещё 5 минут.','Курицу вынуть, мясо снять с костей и вернуть в суп. Посыпать зеленью.']::text[], 'https://1000.menu/cooking/65439-kurinyi-sup-s-cvetnoi-kapustoi', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
