insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-mastava', 'Мастава', 'Узбекский густой суп с говядиной, рисом и овощами', 'soup', array['lunch']::text[], 35, 75, 12, 3, 'red-meat', array['на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить ему порцию до соли, перца и чили, мясо нарезать мелко.', array['Рис промыть и замочить в холодной воде. Мясо нарезать небольшими кубиками, картофель и морковь — мелкими кубиками, с помидоров снять кожицу и нарезать.','В кастрюле с толстым дном обжарить лук на масле 3 минуты, добавить мясо и жарить, помешивая, на медленном огне 15 минут.','Положить морковь и готовить 5 минут, затем помидоры и болгарский перец — ещё 3 минуты.','Добавить картофель, зиру и кориандр и готовить вместе 5 минут, помешивая.','Влить 3 л горячей воды и варить на среднем огне 20–25 минут до мягкости мяса.','Всыпать рис без воды и варить ещё 10 минут до его готовности. Посолить и поперчить, хлопья чили класть в тарелки взрослым.']::text[], 'https://1000.menu/cooking/5140-mastava', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
