insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-kapreze', 'Капрезе', 'Помидоры с моцареллой и базиликом под оливковым маслом', 'salad', array['lunch','dinner']::text[], 10, 10, 4, 1, 'dairy', array['быстро','без плиты']::text[], array['summer']::text[], '{}'::text[], 'adapt', 'Отложить ему помидоры с моцареллой до уксуса и перца и нарезать мелкими кусочками.', array['Помидоры и моцареллу нарезать тонкими кружками. Листья базилика промыть и обсушить.','Выложить на блюдо внахлёст, чередуя помидоры, моцареллу и базилик.','Сбрызнуть оливковым маслом и бальзамическим уксусом, посолить и поперчить перед подачей.']::text[], 'https://1000.menu/cooking/28359-salat-kapreze-klassicheskii-s-mocarelloi', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
