insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-tabule', 'Табуле', 'Булгур с горой петрушки, помидорами, огурцом и лимоном', 'salad', array['lunch','dinner']::text[], 20, 40, 4, 1, 'none', array['постное']::text[], array['summer','autumn']::text[], '{}'::text[], 'adapt', 'Отложить ему порцию без чеснока и перца, лимонного сока — совсем немного.', array['Булгур отварить по инструкции на упаковке и полностью остудить.','Огурец и помидоры нарезать очень мелкими кубиками.','Петрушку и листья мяты мелко порубить острым ножом, чтобы зелень не пустила сок.','Соединить булгур, овощи, зелень и тёртый чеснок. Заправить лимонным соком, оливковым маслом, солью и перцем, перемешать и сразу подавать.']::text[], 'https://menunedeli.ru/recipe/tabule-s-bulgurom-recept-klassicheskij/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
