insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-kartofelnyi-s-ogurtsami', 'Картофельный салат с солёными огурцами', 'Варёная картошка, морковь и огурчики с маслом, как в детском саду', 'salad', array['lunch','dinner']::text[], 15, 60, 6, 2, 'none', array['постное','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Соль ему не добавлять — хватит огурцов, а огурцов положить поменьше.', array['Картофель и морковь сварить в кожуре до мягкости, около 25 минут, слить воду и остудить.','С солёных огурцов срезать кожицу и нарезать некрупным кубиком.','Лук мелко нарезать и ошпарить кипятком, чтобы ушла горечь.','Очистить и нарезать картофель и морковь такими же кубиками, соединить с огурцами и луком.','Слегка посолить и заправить маслом перед подачей. Можно посыпать зелёным луком.']::text[], 'https://menunedeli.ru/recipe/kartofelnyj-salat-s-solenymi-ogurcami-kak-v-detskom-sadu/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
