insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-muzhskoi-kapriz', 'Мужской каприз', 'Слоёный салат с говядиной, маринованным луком, яйцом и сыром', 'salad', array['lunch','dinner']::text[], 30, 110, 4, 1, 'red-meat', array['праздничное','выходные']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить ему отварную говядину, яйцо и немного тёртого сыра без лука и майонеза, заправить ложкой сметаны.', array['Говядину залить холодной водой с лавровым листом и солью и варить куском 1–1,5 часа до мягкости. Остудить в бульоне.','Яйца сварить вкрутую, 10 минут, и остудить в холодной воде.','Лук нарезать тонкими четвертькольцами, перемешать с уксусом, сахаром, солью и перцем и оставить на 15–20 минут.','Говядину нарезать небольшими кубиками, яйца порубить, сыр натереть.','В кольце выложить слоями: мясо с солью, перцем и майонезом, отжатый лук, яйца с сеткой майонеза, сверху сыр.','Убрать в холодильник минимум на 30 минут, чтобы слои пропитались.']::text[], 'https://menunedeli.ru/recipe/salat-muzhskoj-kapriz-recept-klassicheskij-s-govyadinoj/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
