insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-kuritsa-s-ananasom', 'Салат с курицей и ананасом', 'Курица, ананас, кукуруза и яйца с сыром — праздничная классика', 'salad', array['lunch','dinner']::text[], 25, 40, 4, 1, 'poultry', array['праздничное','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить ему курицу, ананас, кукурузу и яйцо до майонеза, заправить сметаной или йогуртом.', array['Куриное филе положить в холодную воду с лавровым листом, довести до кипения, накрыть, выключить огонь и оставить на 20 минут.','Яйца сварить вкрутую, остудить и натереть на тёрке. Сыр натереть на мелкой тёрке.','С ананасов и кукурузы слить жидкость, ананасы нарезать кубиками.','Курицу обсушить, остудить и нарезать такими же кубиками.','Смешать всё, заправить майонезом и посолить по вкусу.']::text[], 'https://eda.rambler.ru/recepty/salaty/salat-s-kuricey-i-ananasami-klassicheskiy-187681', 'eda.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
