insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-morkov-po-koreiski', 'Морковь по-корейски', 'Острая морковь с чесноком и кориандром, хранится несколько дней', 'salad', array['lunch','dinner']::text[], 20, 30, 6, 5, 'none', array['быстро','постное','бюджетное']::text[], array['any']::text[], '{}'::text[], 'skip', 'Уксус, чеснок и острое ему нельзя. Отложить тёртую морковь до приправ и заправить сметаной или маслом.', array['Морковь натереть на тёрке для корейской моркови, посолить и перемять руками. Оставить на 10 минут.','Добавить сахар, уксус, паприку, кориандр и мелко натёртый чеснок.','Масло сильно разогреть на сковороде и сразу вылить на морковь. Перемешать.','Есть можно сразу, но вкуснее, когда постоит в холодильнике.']::text[], 'https://www.edimdoma.ru/retsepty/148835-morkov-po-koreyski', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
