insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-morkov-s-syrom', 'Морковь с сыром и чесноком', 'Тёртая морковь с сыром и чесноком под сметаной за 15 минут', 'salad', array['lunch','dinner']::text[], 15, 15, 4, 1, 'dairy', array['быстро','без плиты','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить ему морковь с сыром и сметаной до чеснока, морковь натереть мельче.', array['Морковь очистить и нарезать тонкой соломкой или натереть на тёрке для корейской моркови.','Сыр натереть на крупной тёрке, чеснок — на мелкой или пропустить через пресс.','Соединить морковь, сыр и чеснок, заправить сметаной, посолить и перемешать.']::text[], 'https://1000.menu/cooking/33833-salat-iz-morkovi-s-chesnokom-i-syrom', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
