insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-gorbusha-s-risom', 'Салат с горбушей и рисом', 'Консервированная горбуша с рисом, яйцом и огурцом', 'salad', array['lunch','dinner']::text[], 20, 40, 6, 1, 'fish', array['бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить ему рис, рыбу, яйцо и огурец до майонеза, заправить ложкой сметаны. Рыбу проверить на косточки.', array['Рис промыть и сварить в подсоленной воде до готовности, откинуть и остудить.','Яйца сварить вкрутую, 9 минут, остудить и нарезать.','С горбуши слить жидкость, удалить крупные кости и размять вилкой.','Огурец нарезать мелкими кубиками, зелень порубить.','Соединить всё, заправить майонезом, поперчить и при необходимости посолить.']::text[], 'https://1000.menu/cooking/43228-salat-s-gorbushei-konservirovannoi-risom-i-yaicom', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
