insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-zapechyonnyi-perets-s-brynzoi', 'Салат из запечённого перца с брынзой', 'Печёный сладкий перец с помидорами, зеленью и брынзой', 'salad', array['lunch','dinner']::text[], 20, 45, 5, 1, 'dairy', array['духовка']::text[], array['summer','autumn']::text[], '{}'::text[], 'adapt', 'Отложить ему перец с помидорами без чеснока. Брынзы — чуть-чуть, она солёная.', array['Перцы смазать маслом и запекать в духовке при 200° около 15 минут.','Горячие перцы сложить в пакет, завязать и оставить на 15 минут — кожица легко снимется.','Помидоры нарезать крупными кубиками, зелень и чеснок мелко порубить.','Перцы очистить от кожицы и семян и нарезать крупными кусками.','Смешать перец, помидоры, чеснок и зелень, посолить, полить маслом и лимонным соком. Сверху выложить кубики брынзы.']::text[], 'https://www.iamcook.ru/showrecipe/2125', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
