insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-tykva-morkov-yabloko', 'Салат из тыквы, моркови и яблока', 'Сырая тыква, морковь и яблоко с лимонной заправкой — сладко и сочно', 'salad', array['lunch','dinner']::text[], 15, 15, 4, 1, 'none', array['быстро','без плиты','постное','бюджетное','детское']::text[], array['autumn','winter']::text[], '{}'::text[], 'ok', 'Натереть ему на мелкой тёрке.', array['Для заправки смешать оливковое масло и лимонный сок, по желанию — немного сахара.','Тыкву и морковь очистить и натереть на крупной тёрке.','Яблоко натереть последним, чтобы не потемнело, и сразу полить заправкой.','Перемешать и дать постоять 5–10 минут.']::text[], 'https://www.iamcook.ru/showrecipe/12725', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
