insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-nezhnost', 'Салат «Нежность» с курицей и черносливом', 'Слоёный праздничный салат: курица, чернослив, огурец, орехи и яйца', 'salad', array['lunch','dinner']::text[], 30, 180, 6, 1, 'poultry', array['праздничное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Ему курицу, огурец, яйцо и мелко нарезанный распаренный чернослив без орехов и майонеза, со сметаной.', array['Куриное филе сварить в подсоленной воде, около 30 минут, остудить и нарезать кубиками.','Яйца сварить, остудить и натереть на тёрке. Огурец нарезать кубиками.','Чернослив залить горячей водой на 5 минут, промыть и нарезать. Орехи подсушить на сухой сковороде и порубить.','Выложить слоями, промазывая каждый тонким слоем майонеза: курица, чернослив, огурец, орехи, сверху яйца.','Убрать в холодильник на 2–3 часа, чтобы салат пропитался.']::text[], 'https://www.gastronom.ru/recipe/55828/salat-nezhnost-s-kuricej-chernoslivom-i-greckimi-orehami', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
