insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-obzhorka', 'Обжорка', 'Говядина из бульона с жареным луком, морковью и солёными огурцами', 'salad', array['lunch','dinner']::text[], 20, 100, 4, 2, 'red-meat', '{}'::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить ему говядину кусочками без зажарки, огурцов и майонеза, с ложкой сметаны.', array['Говядину сварить до мягкости или взять мясо после бульона. Нарезать кубиками.','Лук нарезать полукольцами, морковь натереть на крупной тёрке. Обжарить вместе на масле до мягкости и остудить.','Огурцы нарезать кубиками.','Смешать мясо, огурцы и зажарку, заправить майонезом и при необходимости посолить.']::text[], 'https://www.gastronom.ru/recipe/63303/salat-novogodniaia-obzhorka', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
