insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-nut-s-kukuruzoi', 'Салат с нутом и кукурузой', 'Нут, кукуруза, помидоры и сладкий перец с медово-уксусной заправкой', 'salad', array['lunch','dinner']::text[], 15, 15, 4, 1, 'legume', array['быстро','без плиты','постное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить ему помидоры, перец, кукурузу и размятый нут без лука и заправки, полить маслом. Бобовые — не чаще 2–3 раз в неделю.', array['Для заправки взбить вилкой оливковое масло, уксус, мёд и измельчённый чеснок и дать постоять.','Листья салата порвать и выложить в салатник, сверху нарезанные помидоры.','Добавить перец кусочками, кукурузу без жидкости, тонко нарезанный репчатый и рубленый зелёный лук.','Положить нут, слегка перемешать и полить заправкой.']::text[], 'https://www.iamcook.ru/showrecipe/18945', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
