insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-tunets-s-beloi-fasolyu', 'Салат с тунцом и белой фасолью', 'Тунец, белая фасоль, хрустящая морковь и маринованный лук', 'salad', array['lunch','dinner']::text[], 20, 40, 6, 1, 'fish', array['будни']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить ему тунца, фасоль и морковь без маринованного лука, заправить маслом, фасоль размять.', array['Лук нарезать тонкими полукольцами и залить смесью 200 мл воды и яблочного уксуса на 15–20 минут.','Морковь нарезать тонкими широкими пластинами, опустить в горячую подсоленную воду на 1 минуту, откинуть и остудить — она должна хрустеть.','Тунца размять вилкой, с фасоли слить жидкость, листья салата промыть и обсушить.','Сложить в салатник тунца, фасоль, морковь, отжатый лук, петрушку и порванные листья салата.','Заправить оливковым маслом, при необходимости посолить и дать немного постоять.']::text[], 'https://www.gastronom.ru/recipe/48279/salat-s-tuncom-i-beloj-fasolyu', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
